/** 酱微博：单轮廓远程前端启动器 */
const JWR2_TAG = '[酱微博]';
const JWR2_BUILD = '20261009-safe-embedded-v7';
const JWR2_FRONTEND_URL = 'https://fchris1219-del.github.io/jiang-weibo-oneframe-v2/weibo.html?v=ee68adb';
const JWR2_ROOT_ID = 'jwr2-root';
const JWR2_BRIDGE_KEY = '__JWR2_BRIDGE__';
const JWR2_INSTANCE_KEY = '__JWR2_CLEANUP__';
const JWR2_SETTINGS_KEY = 'jiang_weibo_oneframe_v2';
const JWR2_CHAT_KEY = 'jiang_weibo_oneframe_v2';
// 导出角色酒馆脚本时只替换这一行；null 表示使用远程 HTML 的系统默认预设。
const JWR2_EMBEDDED_HTML = "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
<title>小微博</title>
<style>
:root{
  --orange:#ff8200;
  --orange2:#ff8140;
  --blue:#507daf;
  --text:#333;
  --sub:#939393;
  --line:#f0f0f0;
  --bg:#f7f7f7;
  --card:#fff;
}
.ai-dot{width:22px;height:22px;border-radius:50%;border:none;background:var(--orange);color:#fff;
  font-size:12px;cursor:pointer;margin-right:4px;box-shadow:0 0 0 2px rgba(255,130,0,.22);transition:transform .16s ease,box-shadow .16s ease,background .16s ease}
@media(hover:hover){.ai-dot:hover{transform:translateY(-1px) scale(1.08);box-shadow:0 0 0 4px rgba(255,130,0,.18),0 5px 12px rgba(255,130,0,.2)}}
.ai-dot.loading{background:#d76c00;cursor:wait;animation:pullSpin .85s linear infinite;box-shadow:0 0 0 4px rgba(255,130,0,.2)}
@keyframes pullSpin{to{transform:rotate(360deg)}}
.acts .ai-gen{color:#fff;background:var(--orange);border-radius:12px;margin:6px 4px;padding:6px 0;font-size:11px;font-weight:600}
.msg-ai-bar button,.page-ai-bar button{
  width:100%;height:36px;border:none;border-radius:18px;background:var(--orange);color:#fff;
  font-size:14px;font-weight:600;cursor:pointer
}
.page-ai-bar button{font-size:13px}
.gen-bubble{
  margin:8px 0 2px;display:inline-flex;align-items:center;gap:6px;
  max-width:100%;padding:7px 12px;border-radius:14px 14px 14px 4px;
  background:#fff5eb;color:#c96800;font-size:12px;line-height:1.4;
  border:1px solid #ffe0bf;cursor:pointer
}
.gen-bubble b{font-weight:600;color:var(--orange)}
.float-toast{
  position:absolute;left:50%;bottom:78px;transform:translateX(-50%);
  z-index:40;max-width:86%;padding:10px 16px;border-radius:20px;
  background:rgba(0,0,0,.78);color:#fff;font-size:13px;line-height:1.4;
  text-align:center;pointer-events:none;opacity:0;transition:opacity .2s;
  box-shadow:0 6px 20px rgba(0,0,0,.18)
}
.float-toast.show{opacity:1}
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{width:100%;height:100%;margin:0;padding:0;background:transparent;
  font-family:-apple-system,"PingFang SC","Helvetica Neue","Microsoft YaHei",sans-serif;color:var(--text)}
body{display:grid;place-items:center;overflow:hidden}
#app{
  width:100%;height:100%;margin:0;background:var(--bg);
  border-radius:22px;overflow:hidden;position:relative;
  box-shadow:0 24px 80px rgba(0,0,0,.42);display:flex;flex-direction:column;
}
/* status */
.status{height:30px;padding:0 10px 0 14px;display:flex;align-items:center;gap:8px;
  font-size:11px;color:#111;background:var(--card);flex:0 0 auto;border-bottom:1px solid #f5f5f5}
.status .status-spacer{flex:1}.status .host-btn{width:24px;height:24px;border:0;border-radius:8px;
  background:transparent;color:#777;font-size:17px;line-height:1;cursor:pointer}.status .host-btn:active{background:#f1f1f1}
/* screens */
.screen{display:none;flex:1;min-height:0;flex-direction:column;background:var(--bg)}
.screen.on{display:flex}
.scroll{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch}
.scroll::-webkit-scrollbar{width:0}

/* home top */
.home-top{background:var(--card);padding:4px 12px 0;flex:0 0 auto;border-bottom:1px solid #f5f5f5}
.home-top .row{display:flex;align-items:center;height:40px}
.home-top .tabs{flex:1;display:flex;justify-content:center;gap:22px;font-size:16px;color:#666}
.home-top .tabs span{position:relative;padding-bottom:8px;cursor:pointer}
.home-top .tabs span.on{color:#111;font-weight:700}
.home-top .tabs span.on::after{content:"";position:absolute;left:50%;bottom:0;transform:translateX(-50%);
  width:18px;height:3px;background:var(--orange);border-radius:2px}
.icon-btn{width:32px;height:32px;border:none;background:transparent;font-size:18px;cursor:pointer;color:#333;position:relative}
.plus{width:28px;height:28px;border-radius:50%;background:var(--orange);color:#fff;border:none;
  font-size:20px;line-height:1;cursor:pointer;font-weight:500}

/* plus menu */
.plus-menu{
  position:absolute;top:62px;right:10px;z-index:20;background:#4a4a4a;color:#fff;
  border-radius:10px;padding:6px 0;min-width:140px;display:none;
  box-shadow:0 8px 24px rgba(0,0,0,.25);pointer-events:none
}
.plus-menu.show{display:block;pointer-events:auto}
.plus-menu::before{
  content:"";position:absolute;top:-6px;right:14px;border-left:6px solid transparent;
  border-right:6px solid transparent;border-bottom:6px solid #4a4a4a
}
.plus-menu div{padding:10px 16px;font-size:14px;cursor:pointer;display:flex;align-items:center;gap:10px}
.plus-menu div:active{background:rgba(255,255,255,.08)}
.plus-menu i{width:18px;text-align:center;font-style:normal}

/* feed card */
.post{background:var(--card);padding:12px 14px 10px;border-bottom:8px solid var(--bg)}
.post .lock{font-size:11px;color:var(--sub);margin-bottom:8px}
.visibility-chip{display:inline-flex;align-items:center;gap:4px;padding:3px 7px;border-radius:10px;background:#f4f4f4;color:#888;font-size:10px;margin-bottom:7px}
.shared-post{margin-top:7px;padding:9px 10px;border-radius:9px;background:#f6f6f6;border:1px solid #e9e9e9;cursor:pointer;max-width:260px}
.shared-post .sp-author{font-size:11px;color:#66708b;font-weight:600}.shared-post .sp-text{font-size:12px;line-height:1.45;margin-top:3px;color:#444;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.post .hd{display:flex;gap:10px;align-items:center}
.post .av{width:40px;height:40px;border-radius:50%;background:#ffd6c2;flex:0 0 auto;
  display:flex;align-items:center;justify-content:center;font-size:16px;overflow:hidden}
.post .av img,.me-av img,.cmt .av img,.post-bar .mini img,.msg-row .ico img{
  width:100%;height:100%;object-fit:cover;display:block;border-radius:50%}
.post .nm{color:var(--orange);font-size:15px;font-weight:600}
.post .sub{font-size:11px;color:var(--sub);margin-top:1px}
.post .txt{margin-top:8px;font-size:15px;line-height:1.65;white-space:pre-wrap;word-break:break-word}
.post .quote{margin-top:8px;background:#f7f7f7;border-radius:6px;padding:10px}
.post .quote .at{color:var(--blue)}
.fake-pic{
  margin-top:8px;height:160px;border-radius:6px;background:#ececec;
  display:flex;align-items:center;justify-content:center;text-align:center;
  color:#888;font-size:13px;padding:16px;line-height:1.5;position:relative
}
.fake-pic b{display:block;color:#666;font-weight:500;margin-bottom:4px;font-size:12px}
.post-bar{margin-top:10px;display:flex;align-items:center;gap:8px}
.post-bar .mini{width:24px;height:24px;border-radius:50%;background:#ffd6c2;flex:0 0 auto;
  display:flex;align-items:center;justify-content:center;font-size:11px}
.post-bar .inp{
  flex:1;height:32px;border-radius:16px;background:#f2f2f2;border:none;
  padding:0 12px;font-size:12px;color:#999;display:flex;align-items:center;cursor:pointer
}
.acts{display:flex;margin-top:6px;border-top:1px solid #f5f5f5}
.acts div{flex:1;text-align:center;padding:9px 0;font-size:12px;color:#8c8c8c;cursor:pointer}
.acts div:active{opacity:.6}
.pull-bar{
  background:var(--card);padding:8px 14px 10px;border-bottom:1px solid #f5f5f5;flex:0 0 auto
}
.pull-bar button{
  width:100%;height:34px;border:1px solid #ffd4a8;border-radius:17px;
  background:#fff5eb;color:var(--orange);font-size:13px;font-weight:600;cursor:pointer
}
.pull-bar button:disabled{opacity:.55;cursor:wait}
@media(hover:hover){.pull-bar button:not(:disabled):hover{background:#fff0df;box-shadow:0 4px 12px rgba(255,130,0,.12);transform:translateY(-1px)}}
.pull-bar button{transition:background .16s ease,box-shadow .16s ease,transform .16s ease,color .16s ease}
.pull-bar button.loading{position:relative;background:#ffedd9!important;color:#c85f00!important;border-color:#ffb96f!important;opacity:1}
.pull-bar button.loading::before{content:"";display:inline-block;width:11px;height:11px;margin-right:7px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;vertical-align:-2px;animation:pullSpin .75s linear infinite}
.feed-cmts{padding:6px 2px 2px;border-top:1px solid #f5f5f5}
.feed-cmts .fc{
  font-size:12px;line-height:1.5;margin:4px 0;color:#333
}
.feed-cmts .fc b{color:#666a8c;font-weight:500}
.feed-cmts .more{font-size:11px;color:#999;margin-top:2px}

/* messages */
.msg-top{background:var(--card);height:44px;display:flex;align-items:center;justify-content:center;
  gap:28px;position:relative;border-bottom:1px solid #f5f5f5;flex:0 0 auto}
.msg-top span{font-size:15px;color:#666;cursor:pointer;padding-bottom:8px;position:relative}
.msg-top span.on{color:#111;font-weight:700}
.msg-top span.on::after{content:"";position:absolute;left:50%;bottom:0;transform:translateX(-50%);
  width:20px;height:3px;background:var(--orange);border-radius:2px}
.msg-banner{background:#fff5eb;color:var(--orange);font-size:12px;padding:8px 14px;
  display:flex;justify-content:space-between;align-items:center}
.msg-row{background:var(--card);display:flex;align-items:center;gap:12px;padding:12px 14px;
  border-bottom:1px solid #f2f2f2;cursor:pointer}
.msg-row .ico{width:42px;height:42px;border-radius:50%;display:flex;align-items:center;
  justify-content:center;color:#fff;font-size:18px;flex:0 0 auto}
.msg-row .ico.at{background:#4a90e2}
.msg-row .ico.cmt{background:#5ecf6a}
.msg-row .ico.like{background:var(--orange)}
.msg-row .mid{flex:1;min-width:0}
.msg-row .t{font-size:15px;font-weight:500}
.msg-row .p{font-size:12px;color:var(--sub);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.msg-row .right{text-align:right;flex:0 0 auto}
.msg-row .tm{font-size:11px;color:var(--sub)}
.msg-row .dot{width:8px;height:8px;border-radius:50%;background:#f44;margin:6px 0 0 auto}
.chev{color:#ccc;font-size:16px}

/* me */
.me-top{background:var(--card);padding:10px 14px 16px}
.me-tools{display:flex;justify-content:flex-end;gap:14px;font-size:18px;color:#333;margin-bottom:8px}
.me-hd{display:flex;gap:12px;align-items:center}
.me-av{width:64px;height:64px;border-radius:50%;background:#ffd6c2;
  display:flex;align-items:center;justify-content:center;font-size:24px}
.me-name{font-size:18px;font-weight:700}
.me-bio{font-size:12px;color:var(--sub);margin-top:4px}
.me-stats{display:flex;margin-top:16px;text-align:center}
.me-stats div{flex:1}
.me-stats b{display:block;font-size:16px}
.me-stats span{font-size:11px;color:var(--sub)}
.me-grid{background:var(--card);margin-top:8px;padding:14px 8px 6px;display:grid;grid-template-columns:repeat(4,1fr);gap:14px 0}
.me-grid div{text-align:center;font-size:11px;color:#555;cursor:pointer}
.me-grid i{display:block;font-size:22px;font-style:normal;margin-bottom:4px;color:#666}
.me-card{background:var(--card);margin:8px 0 0;padding:14px;border-radius:0}
.set-row{margin-top:12px}
.set-row label{display:block;font-size:12px;color:#666;margin-bottom:4px}
.set-row input[type=text],.set-row input[type=number],.set-row input[type=password],.set-row select,.set-row textarea{
  width:100%;border:1px solid #eee;border-radius:8px;padding:0 10px;
  font:inherit;font-size:14px;background:#fafafa;outline:none
}
.set-row input[type=text],.set-row input[type=number],.set-row input[type=password],.set-row select{height:36px}
.set-row textarea{padding:8px 10px;min-height:72px;resize:vertical;line-height:1.45}
.set-row.half{display:flex;gap:8px}
.set-row.half > div{flex:1;min-width:0}
.lore-sec-box{margin-top:10px;padding-top:8px;border-top:1px dashed #eee}
.set-row .chk{display:flex;align-items:flex-start;gap:8px;font-size:13px;color:#444;line-height:1.45}
.set-row .chk input{margin-top:3px}
.set-actions{display:flex;gap:8px;margin-top:14px}
.set-actions button{
  flex:1;height:36px;border:none;border-radius:18px;font-size:14px;font-weight:600;cursor:pointer
}
.set-actions .save{background:var(--orange);color:#fff}
.set-actions .reset{background:#f2f2f2;color:#666}
.set-hint{font-size:11px;color:#999;margin-top:6px;line-height:1.5}
.lore-pick-list{
  margin-top:10px;max-height:260px;overflow:auto;border:1px solid #eee;border-radius:10px;
  background:#fafafa;padding:6px 8px
}
.lore-pick-list .lore-empty{font-size:12px;color:#999;padding:14px 6px;text-align:center;line-height:1.5}
.lore-pick-nav{
  display:flex;align-items:center;gap:8px;padding:4px 2px 10px;border-bottom:1px solid #eee;margin-bottom:4px
}
.lore-pick-nav .back{
  border:none;background:#f2f2f2;color:#666;border-radius:12px;padding:4px 10px;font-size:12px;cursor:pointer
}
.lore-pick-nav .tt{flex:1;font-size:12px;font-weight:600;color:#333;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.lore-book-row{
  display:flex;align-items:center;gap:8px;padding:10px 6px;border-bottom:1px solid #f0f0f0;cursor:pointer;
  transition:background .16s ease,color .16s ease,transform .16s ease
}
@media(hover:hover){.lore-book-row:hover{background:#fffaf6;color:#d85f0b;transform:translateX(2px)}}
.lore-book-row:active{background:#ffe9d8;transform:translateX(0)}
.lore-book-row .meta{flex:1;min-width:0}
.lore-book-row .nm{font-weight:600;font-size:13px;color:#222}
.lore-book-row .bk{color:#999;font-size:11px;margin-top:2px}
.lore-book-row .chev{color:#ccc;font-size:18px;flex:0 0 auto}
.lore-pick-item{
  display:flex;align-items:flex-start;gap:8px;padding:8px 4px;border-bottom:1px solid #f0f0f0;
  font-size:12px;color:#333;line-height:1.4
}
.lore-pick-item:last-child{border-bottom:0}
.lore-pick-item input{margin-top:2px;flex:0 0 auto}
.lore-pick-item .meta{flex:1;min-width:0}
.lore-pick-item .nm{font-weight:600;font-size:12px}
.lore-pick-item .bk{color:#999;font-size:10px;margin-top:1px}
.lore-pick-item .pv{color:#888;font-size:11px;margin-top:3px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}

/* profile home (参考 微博开场) */
.pf-wrap{background:var(--bg);min-height:100%}
.pf-profile{background:var(--card);padding:18px 14px 14px;border-bottom:6px solid var(--bg)}
.pf-profile .row{display:flex;align-items:center;gap:12px}
.pf-av{width:56px;height:56px;border-radius:50%;background:#ffd6c2;flex:0 0 auto;overflow:hidden;
  display:flex;align-items:center;justify-content:center;font-size:22px}
.pf-av img{width:100%;height:100%;object-fit:cover;display:block}
.pf-name{font-size:17px;font-weight:700}
.pf-uid{color:var(--sub);font-size:12px;margin-top:2px}
.pf-bio{margin-top:10px;color:#333;font-size:13px;line-height:1.7}
.pf-stats{display:flex;gap:22px;margin-top:12px;font-size:13px}
.pf-stats b{font-size:15px}
.pf-stats span{color:var(--sub);margin-left:3px}
.pf-tabs{background:var(--card);display:flex;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:3}
.pf-tabs div{flex:1;text-align:center;padding:10px 0;font-size:14px;color:var(--sub)}
.pf-tabs div.on{color:var(--text);font-weight:600;position:relative}
.pf-tabs div.on::after{content:"";position:absolute;left:50%;transform:translateX(-50%);
  bottom:0;width:26px;height:2px;background:var(--orange);border-radius:2px}
.pf-end{text-align:center;color:#c4c4c4;font-size:12px;padding:18px 0 26px}
.pf-follow{
  margin-top:12px;width:100%;height:34px;border:none;border-radius:17px;
  background:var(--orange);color:#fff;font-size:14px;font-weight:600;
  letter-spacing:2px;cursor:pointer
}
.pf-follow.on{background:#f5f5f5;color:#666;border:1px solid #e6e6e6;letter-spacing:0}
.pf-follow:active{opacity:.85}
.pf-switch{
  margin-top:10px;width:100%;border:none;background:transparent;
  color:var(--link,#eb7350);font-size:13px;padding:6px 0;cursor:pointer;text-align:left
}
.me-hd{cursor:pointer}
.me-hd:active{opacity:.85}

/* bottom nav */
.tabbar{
  flex:0 0 auto;height:52px;background:rgba(255,255,255,.96);border-top:1px solid #eee;
  display:flex;align-items:center;padding-bottom:2px;z-index:10
}
.tabbar button{
  flex:1;border:none;background:transparent;font-size:10px;color:#666;cursor:pointer;
  display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px 0;position:relative
}
.tabbar button.on{color:#111;font-weight:600}
.tabbar .ico{font-size:18px;line-height:1;position:relative}
.badge-dot,.badge-num{
  position:absolute;background:#f44;border:1.5px solid #fff;pointer-events:none
}
.badge-dot{
  width:8px;height:8px;border-radius:50%;top:-2px;right:-6px
}
.badge-num{
  min-width:16px;height:16px;padding:0 4px;border-radius:8px;
  color:#fff;font-size:10px;font-weight:700;line-height:16px;text-align:center;
  top:-7px;right:-12px;box-sizing:border-box
}
.tabbar .badge-num{top:-6px;right:-14px}
.msg-row{position:relative}
.msg-row .badge-wrap{position:relative;flex:0 0 auto}
.msg-row .ico{position:relative}
.acts [data-act="cm"]{position:relative}
.acts .badge-dot{top:6px;right:calc(50% - 18px)}
.post .gen-bubble{position:relative}
.post .gen-bubble .badge-dot{top:4px;right:8px;border-color:#fff5eb}

/* overlay pages */
.page{
  position:absolute;inset:0;background:var(--card);z-index:30;
  transform:translateX(100%);transition:transform .25s ease;display:flex;flex-direction:column;
  pointer-events:none; /* 滑出时绝不挡点击；酒馆 iframe 里 transform 仍可能吃事件 */
}
.page.show{transform:translateX(0);pointer-events:auto}
.page-top{height:44px;display:flex;align-items:center;padding:0 10px;border-bottom:1px solid #f0f0f0;flex:0 0 auto}
.page-top .back{font-size:28px;width:32px;border:none;background:none;cursor:pointer;line-height:1;font-weight:300}
.page-top .tt{flex:1;text-align:center;font-size:16px;font-weight:600}
.page-body{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch}

/* chat */
.chat{background:var(--bg);min-height:100%;padding:12px;display:flex;flex-direction:column;gap:8px}
.bub{max-width:78%;padding:8px 11px;border-radius:8px;font-size:14px;line-height:1.5;word-break:break-word}
.bub.npc{background:#fff;align-self:flex-start;border:1px solid #eee}
.bub.me{background:#fff1e6;align-self:flex-end}
.bub .tm{font-size:10px;color:var(--sub);margin-top:4px}
.chat-bar{display:flex;gap:8px;padding:8px 10px;border-top:1px solid #eee;background:#fff}
.chat-bar input{flex:1;border:1px solid #eee;border-radius:16px;padding:8px 12px;font:inherit;outline:none}
.chat-bar button{border:none;background:var(--orange);color:#fff;border-radius:16px;padding:0 14px;font-size:13px}
.dm-thread-layout{height:100%;min-height:0;display:flex;flex-direction:column;background:var(--bg)}
.dm-thread-layout>.chat{flex:1;min-height:0;overflow-y:auto;-webkit-overflow-scrolling:touch}
.dm-thread-layout>.page-ai-bar,.dm-thread-layout>.chat-bar{flex:0 0 auto;background:#fff}
.dm-thread-layout>.chat-bar{padding-bottom:max(8px,env(safe-area-inset-bottom))}

/* modal */
.mask{position:absolute;inset:0;background:rgba(0,0,0,.45);z-index:40;display:none;align-items:flex-end;justify-content:center;pointer-events:none}
.mask.show{display:flex;pointer-events:auto}
.sheet{width:calc(100% - 20px);margin:0 10px 10px;background:#fff;border-radius:14px;padding:16px 16px 20px;overflow:hidden}
