.npc-editor-list{display:flex;flex-direction:column;gap:10px;margin-top:12px}.npc-editor-card{border:1px solid #eee;border-radius:12px;background:#fafafa;overflow:hidden}.npc-editor-head{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:8px;padding:11px;cursor:pointer}.npc-editor-head:hover{background:#fff7f0}.npc-editor-head strong{min-width:0;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.npc-editor-ident{font-size:10px;color:#999;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.npc-editor-chev{color:#aaa;font-size:15px;transition:transform .18s ease}.npc-editor-card.open .npc-editor-chev{transform:rotate(180deg);color:#dd6811}.npc-editor-body{display:none;padding:0 11px 11px;border-top:1px solid #eee}.npc-editor-card.open .npc-editor-body{display:block}.npc-editor-actions{display:flex;justify-content:flex-end;margin-top:10px}.npc-editor-actions button{border:0;background:#fff0ee;color:#c8493f;border-radius:9px;padding:7px 10px;font-size:11px;cursor:pointer}.npc-lore-select{width:100%;min-height:88px;border:1px solid #e7e7e7;border-radius:8px;background:#fff;padding:5px;font:inherit;font-size:11px}.npc-account-switch{padding:10px 14px;background:#fff;border-bottom:1px solid #eee;display:flex;gap:8px;align-items:center}.npc-account-switch label{font-size:11px;color:#999}.npc-account-switch select{flex:1;height:34px;border:1px solid #eee;border-radius:17px;background:#fafafa;padding:0 12px;font:inherit;font-size:12px}
.visibility-picker{margin-top:10px;padding:10px;border:1px solid #eee;border-radius:10px;background:#fafafa}.visibility-picker .vp-options{display:flex;gap:7px;flex-wrap:wrap}.visibility-picker label{font-size:12px;color:#555}.visibility-group{margin-top:8px;display:grid;grid-template-columns:1fr 1fr;gap:6px}.visibility-group label{padding:7px 8px;border-radius:8px;background:#fff;border:1px solid #eee;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
