.book-bulk{display:flex;align-items:center;gap:5px;flex:0 0 auto}.book-bulk button{border:1px solid #eee;background:#fff;color:#777;border-radius:8px;padding:5px 7px;font-size:10px;cursor:pointer}.book-bulk button.primary{border-color:#ffc89f;color:#d6630d;background:#fff8f2}
.id-pool-help{margin-top:7px;padding:8px 9px;border-radius:8px;background:#f7f7f7;color:#777;font-size:10px;line-height:1.55}
.id-pool-list{display:flex;flex-direction:column;gap:8px;margin-top:10px}.id-pool-empty{padding:13px;border:1px dashed #ddd;border-radius:10px;text-align:center;color:#aaa;font-size:10px;background:#fafafa}.id-pool-row{display:grid;grid-template-columns:minmax(0,1.15fr) 72px minmax(0,1.35fr) 32px;gap:7px;align-items:end;padding:9px;border:1px solid #eee;border-radius:11px;background:#fafafa}.id-pool-field{min-width:0}.id-pool-field label{display:block;margin:0 0 4px;color:#999;font-size:9px}.id-pool-field input{box-sizing:border-box;width:100%;height:34px;border:1px solid #e5e5e5;border-radius:8px;background:#fff;padding:0 8px;font:inherit;font-size:11px;outline:none}.id-pool-field input:focus{border-color:#ef9b5f;box-shadow:0 0 0 3px rgba(239,155,95,.12)}.id-pool-remove{width:32px;height:34px;border:0;border-radius:8px;background:#fff0ee;color:#c8493f;font-size:16px;cursor:pointer}
.generator-box{margin-top:11px;padding:10px;border:1px solid #f1dfd1;border-radius:11px;background:#fffaf6}.generator-title{font-size:11px;font-weight:800;color:#805536}.generator-lore-list{margin-top:8px;border:1px solid #eee;border-radius:10px;background:#fff;max-height:260px;overflow:auto}.generator-lore-book{border-bottom:1px solid #f1f1f1}.generator-lore-book:last-child{border-bottom:0}.generator-lore-book summary{display:flex;align-items:center;gap:8px;padding:9px 10px;cursor:pointer;list-style:none}.generator-lore-book summary::-webkit-details-marker{display:none}.generator-lore-book summary strong{flex:1;min-width:0;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.generator-lore-book summary span{font-size:9px;color:#999}.generator-lore-entries{padding:0 8px 8px}.generator-lore-entries .lore-pick-item{margin-top:5px}.utility-loading{position:relative}.utility-loading.loading{pointer-events:none;opacity:.68}.utility-loading.loading::before{content:"";display:inline-block;width:11px;height:11px;margin-right:6px;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;vertical-align:-2px;animation:pullSpin .75s linear infinite}
.scan-term-tools{display:flex;align-items:center;gap:7px;margin-top:7px}.scan-term-tools .mini-action{height:32px}.scan-term-chips{display:flex;flex:1;flex-wrap:wrap;gap:5px;min-width:0}.scan-term-chip{display:inline-flex;align-items:center;gap:5px;max-width:100%;padding:5px 7px;border-radius:999px;background:#fff2e8;color:#a9571e;font-size:10px;line-height:1}.scan-term-chip span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.scan-term-chip button{all:unset;cursor:pointer;color:#d1783a;font-size:12px}.scan-term-empty{color:#aaa;font-size:9px}
.pull-bar{display:grid;grid-template-columns:1fr 1fr;gap:7px}
.pull-bar #allPullBtn{background:var(--orange);border-color:var(--orange);color:#fff}
