<body>
<div id="app">
  <div class="status"><span id="clock">9:41</span><span>5G ▮▮▮▯</span><span class="status-spacer"></span><button class="host-btn" id="hostRefreshBtn" title="刷新前端">↻</button><button class="host-btn" id="hostCloseBtn" title="关闭微博">×</button></div>

  <!-- 微博首页 -->
  <section class="screen on" id="sc-home">
    <div class="home-top">
      <div class="row">
        <button class="ai-dot" id="aiBtn" title="申请AI">✓</button>
        <div class="tabs">
          <span>超话</span>
          <span class="on" data-feed="rec">推荐</span>
          <span data-feed="fol">关注</span>
        </div>
        <button class="plus" id="plusBtn">+</button>
      </div>
      <div class="pull-bar" id="pullBar">
        <button type="button" id="feedPullBtn">刷新推荐 · 拉取 5 条微博</button>
        <button type="button" id="allPullBtn">全部拉取</button>
      </div>
    </div>
    <div class="scroll" id="feedScroll">
      <div id="feed"></div>
    </div>
  </section>

  <!-- 角色/用户微博主页 -->
  <section class="screen" id="sc-video">
    <div class="scroll" id="profileHome"><div class="empty">加载主页…</div></div>
  </section>
  <section class="screen" id="sc-discover"><div class="empty">发现（暂未开放）</div></section>

  <!-- 消息 -->
  <section class="screen" id="sc-msg">
    <div class="msg-top">
      <span>发现群</span>
      <span>动态</span>
      <span class="on">消息</span>
    </div>
    <div class="scroll">
      <div class="msg-banner"><span>打开通知，及时收到互动消息</span><span>×</span></div>
      <div class="msg-ai-bar"><button type="button" id="dmScatterBtn">收路人私信</button></div>
      <div class="msg-row" data-stub="@我的"><div class="ico at">@</div><div class="mid"><div class="t">@我的</div></div><div class="chev">›</div></div>
      <div class="msg-row" data-stub="评论" id="rowComments"><div class="ico cmt" id="icoComments">💬</div><div class="mid"><div class="t">评论</div><div class="p" id="rowCommentsHint">暂无新评论</div></div><div class="right" id="rowCommentsRight"></div><div class="chev">›</div></div>
      <div class="msg-row" data-stub="赞"><div class="ico like">👍</div><div class="mid"><div class="t">赞</div></div><div class="chev">›</div></div>
      <div id="dmList"></div>
    </div>
  </section>

  <!-- 我 -->
  <section class="screen" id="sc-me">
    <div class="scroll">
      <div class="me-top">
        <div class="me-tools">
          <span id="openLogBtn" title="AI原始日志" style="cursor:pointer">🧾</span>
          <span id="openSettingsBtn" title="设置" style="cursor:pointer">⚙</span>
        </div>
        <div class="me-hd" id="meHdOpen" title="打开我的微博主页">
