<script>
(function(){
  // 支持 iframe ?char=&user=&ua=&ca=（正则/扩展注入，避免在正则里塞大脚本）
  try {
    const q = new URLSearchParams(location.search || '');
    const pick = (k) => {
      const v = q.get(k);
      return (v != null && String(v).trim() !== '') ? String(v) : '';
    };
    if (pick('char')) window.charName = pick('char');
    if (pick('user')) window.userName = pick('user');
    if (pick('ua')) window.userAvatarPath = pick('ua');
    if (pick('ca')) window.charAvatarPath = pick('ca');
  } catch (_) {}

  const charName = (typeof window.charName !== 'undefined') ? window.charName : '{{char}}';
  const userName = (typeof window.userName !== 'undefined') ? window.userName : '{{user}}';
  const userAvatarPath = (typeof window.userAvatarPath !== 'undefined') ? window.userAvatarPath : '{{userAvatarPath}}';
  const charAvatarPath = (typeof window.charAvatarPath !== 'undefined') ? window.charAvatarPath : '{{charAvatarPath}}';
  const rawUserName = (!userName || String(userName).includes('{{')) ? '' : String(userName);
  const rawCharName = (!charName || String(charName).includes('{{')) ? '' : String(charName);
  const CURRENT_CHARACTER_TEMPLATE_KEY = String(window.__JWR2_CHAR_KEY__ || [rawCharName || 'char', String(charAvatarPath || '')].join('::'));
  const WB_HOST = window.WeiboHost && typeof window.WeiboHost === 'object' ? window.WeiboHost : null;

  // 参考酒馆原生预设的 in-chat depth：0 最靠近本次任务，数字越大越早注入。
  // AshenBridge 的辅助条目普遍为 depth 4；微博协议/隔离/去重则放到更靠近请求的深度。
  const DEFAULT_PRESET_DEPTHS = Object.freeze({
    native:0, boundary:0, recent:0, dedupe:1, idPool:1, hotMeme:2, npcDm:2, npcAccounts:2, init:2, history:3,
    character:4, persona:4, worldbook:4,
  });
  function normalizePresetDepths(value){
    const src = value && typeof value === 'object' ? value : {};
    const out = { ...DEFAULT_PRESET_DEPTHS };
    Object.keys(out).forEach((key) => { out[key] = Math.max(0, Math.min(20, Number(src[key] ?? out[key]) || 0)); });
    return out;
  }
  function normalizeHistoryContext(value){
    const src = value && typeof value === 'object' ? value : {};
    const legacyMode = ['recent','summary','both','none'].includes(src.mode) ? src.mode : 'recent';
    const hasRecentFlag = typeof src.includeRecentContext === 'boolean';
    const hasSummaryFlag = typeof src.includeSummaryContext === 'boolean';
    const includeRecent = hasRecentFlag ? src.includeRecentContext : (legacyMode === 'recent' || legacyMode === 'both');
    const includeSummary = hasSummaryFlag ? src.includeSummaryContext : (legacyMode === 'summary' || legacyMode === 'both');
    const mode = includeRecent ? (includeSummary ? 'both' : 'recent') : (includeSummary ? 'summary' : 'none');
    const includeOpening = typeof src.includeOpeningContext === 'boolean' ? src.includeOpeningContext : false;
    const includeBaiBai = typeof src.includeBaiBaiHistory === 'boolean' ? src.includeBaiBaiHistory : false;
    const includeAll = src.includeAllContentHistory === true;
    return { includeRecentContext:!!includeRecent, includeSummaryContext:!!includeSummary, includeOpeningContext:includeOpening, includeBaiBaiHistory:includeBaiBai, includeAllContentHistory:includeAll, mode };
  }

  function defaultGlobalConfig(){
    return {
      version: 6,
      api: { mode:'main', source:'custom', url:'', model:'', models:[], temperature:0.8, maxTokens:4096 },
      context: { mode:'recent', includeRecentContext:true, includeSummaryContext:false, includeOpeningContext:false, includeBaiBaiHistory:false, includeAllContentHistory:false, recentMessages:3, manualSummary:'', includeChar:true, includePersona:true, includeScenario:true, includeWorldInfo:true, systemAddon:'', loreScanKeyword:'🩶', loreBookNames:'', lorePortableBindings:[], nativePrompt:'detailed', nativePromptText:'', hotMemeEnabled:true, hotMemePrompt:'', hotMemeManualText:'', hotMemeBookNames:'', hotMemeEntryNames:'', hotMemePortableBindings:[], hotMemeLoreIds:[], hotMemeLoreSnap:[], customIdPool:'', idGenerateCount:20, idGenerateExtra:'', idGenerateAllLore:true, idGenerateIncludeChar:true, idGenerateIncludePersona:true, idGenerateLorePortableBindings:[], npcGenerateCount:6, npcGenerateExtra:'', npcGenerateAllLore:true, npcGenerateIncludeChar:true, npcGenerateIncludePersona:true, npcGenerateLorePortableBindings:[], npcDmEnabled:false, npcDmPrompt:'', npcAccounts:[], generationCounts:{ feed:5, feedComments:5, comments:5, dm:10, dmThread:5, allFeed:5, allChar:1, allDm:10 }, presetDepths:{ ...DEFAULT_PRESET_DEPTHS }, customEntries:[], injectMain:false },
      presetTemplates: [],
      rolePresetTemplates: {},
      activePresetTemplateId: 'system',
      embeddedPresetId: '',
      slots: [{ id:'default', name:'默认档位', initPrompt:'', wbLore:'' }],
    };
  }
  function normalizeGlobalConfig(raw){
    const base = defaultGlobalConfig();
    const value = raw && typeof raw === 'object' ? raw : {};
    const out = {
      ...base,
      ...value,
      api: { ...base.api, ...(value.api || {}) },
      context: { ...base.context, ...(value.context || {}) },
      slots: Array.isArray(value.slots) && value.slots.length ? value.slots : base.slots,
    };
    if (Number(value.version || 0) < 3 && Number(value.context?.recentMessages) === 12) out.context.recentMessages = 3;
    out.context.customEntries = Array.isArray(out.context.customEntries) ? out.context.customEntries : [];
    Object.assign(out.context, normalizeHistoryContext(value.context || out.context));
    out.context.charAccount = normalizePortableCharAccount(out.context.charAccount);
    out.context.npcAccounts = Array.isArray(out.context.npcAccounts) ? out.context.npcAccounts : [];
    out.context.lorePortableBindings = normalizePortableLoreBindings(out.context.lorePortableBindings);
    out.context.hotMemePortableBindings = normalizePortableLoreBindings(out.context.hotMemePortableBindings);
    out.context.idGenerateLorePortableBindings = normalizePortableLoreBindings(out.context.idGenerateLorePortableBindings);
