      box.__jwr2SelectedIds = new Set();
    }
    if (options.resetBook === true || box.__jwr2BookKey === undefined) box.__jwr2BookKey = null;
    const selected = box.__jwr2SelectedIds;
    const disabled = options.disabled === true;
    const notify = () => { try { options.onChange?.([...selected]); } catch (_) {} };
    const renderPage = () => {
      if (!books.length) {
        box.innerHTML = '<div class="lore-empty">未读取到当前挂载世界书，请刷新后重试。</div>';
