      if (box.__jwr2BookKey == null) {
        box.innerHTML = `<div class="lore-empty" style="padding:6px 4px 10px;text-align:left">已读取 ${books.length} 本世界书 · 已选 ${selected.size} 条<br>先选世界书，再选择其中条目</div>` + books.map((book) => {
          const usable = (book.entries || []).filter((item) => !item.disabled);
          const picked = (book.entries || []).filter((item) => selected.has(String(item.id))).length;
          return `<div class="lore-book-row" data-nested-lore-book="${esc(book.key)}">
            <div class="meta"><div class="nm">${esc(book.label)}</div><div class="bk">可用 ${usable.length}/${(book.entries || []).length} 条 · 已选 ${picked}</div></div>
            ${disabled ? '' : `<div class="book-bulk"><button type="button" class="primary" data-nested-lore-bulk="select" data-nested-lore-book-key="${esc(book.key)}">整本勾选</button><button type="button" data-nested-lore-bulk="clear" data-nested-lore-book-key="${esc(book.key)}">取消</button></div>`}
            <div class="chev">›</div>
          </div>`;
        }).join('');
      } else {
        const book = books.find((item) => String(item.key) === String(box.__jwr2BookKey));
        if (!book) { box.__jwr2BookKey = null; renderPage(); return; }
        box.innerHTML = `<div class="lore-pick-nav"><button type="button" class="back" data-nested-lore-back>‹ 世界书</button><div class="tt">${esc(book.label)}</div></div>
          <div class="lore-empty" style="padding:4px 2px 8px;text-align:left">${(book.entries || []).length} 条 · 按 order 降序${disabled ? ' · 当前为自动全量读取' : ''}</div>
          ${(book.entries || []).map((item) => `<label class="lore-pick-item"${item.disabled ? ' style="opacity:.78"' : ''}><input type="checkbox" data-nested-lore-id="${esc(item.id)}" ${selected.has(String(item.id)) ? 'checked' : ''} ${disabled ? 'disabled' : ''}><div class="meta"><div class="nm">${esc(loreDisplayName(item))}</div><div class="bk">order ${esc(String(item.order))}${item.keys?.length ? ' · ' + esc(item.keys.slice(0, 4).join(', ')) : ''}</div><div class="pv">${esc(item.preview || '')}</div></div></label>`).join('')}`;
      }
      box.onclick = (event) => {
        const bulk = event.target.closest('[data-nested-lore-bulk]');
        if (bulk && !disabled) {
          event.preventDefault(); event.stopPropagation();
          const book = books.find((item) => String(item.key) === String(bulk.dataset.nestedLoreBookKey));
          (book?.entries || []).forEach((item) => {
            if (bulk.dataset.nestedLoreBulk === 'select' && !item.disabled) selected.add(String(item.id));
            if (bulk.dataset.nestedLoreBulk === 'clear') selected.delete(String(item.id));
          });
          notify(); renderPage(); return;
        }
        if (event.target.closest('[data-nested-lore-back]')) { box.__jwr2BookKey = null; renderPage(); return; }
        const row = event.target.closest('[data-nested-lore-book]');
        if (row) { box.__jwr2BookKey = row.dataset.nestedLoreBook; renderPage(); }
      };
      box.onchange = (event) => {
        const input = event.target.closest('[data-nested-lore-id]');
        if (!input || disabled) return;
        if (input.checked) selected.add(String(input.dataset.nestedLoreId));
        else selected.delete(String(input.dataset.nestedLoreId));
        notify();
      };
    };
    renderPage();
