  function splitScanTerms(value){
    return [...new Set(String(value || '').split(/[，,\n\r]+/).map((item) => item.trim()).filter(Boolean))];
  }
  function renderScanTermChips(fieldId){
    const field = document.getElementById(fieldId);
    const box = document.querySelector(`[data-scan-chips="${fieldId}"]`);
    if (!field || !box) return;
    const terms = splitScanTerms(field.value);
    box.innerHTML = terms.length ? terms.map((term, index) => `<span class="scan-term-chip"><span>${esc(term)}</span><button type="button" aria-label="删除 ${esc(term)}" data-scan-remove="${esc(fieldId)}" data-scan-index="${index}">×</button></span>`).join('') : '<span class="scan-term-empty">尚未拆分词条</span>';
  }
  function splitScanField(fieldId){
