  function normalizePortableLoreBindings(value){
    const seen = new Set();
    return (Array.isArray(value) ? value : []).map((item) => ({
      book:String(item?.book || '').replace(/^(世界书:|角色书:)/, '').trim(),
      entry:String(item?.entry || item?.name || '').trim(),
    })).filter((item) => {
      const key = item.book.toLowerCase() + '\u0000' + item.entry.toLowerCase();
      if (!item.book || !item.entry || seen.has(key)) return false;
      seen.add(key); return true;
    });
  }
  function portableLoreIds(books, bindings){
    const wanted = normalizePortableLoreBindings(bindings);
    const ids = new Set();
    (books || []).forEach((book) => {
      const bookName = String(book.label || book.key || '').replace(/^(世界书:|角色书:)/, '').trim().toLowerCase();
      const entryNames = new Set(wanted.filter((item) => item.book.toLowerCase() === bookName).map((item) => item.entry.toLowerCase()));
      if (!entryNames.size) return;
      (book.entries || []).forEach((item) => { if (entryNames.has(String(item.name || '').trim().toLowerCase())) ids.add(String(item.id)); });
    });
    return ids;
  }
  function portableBindingsFromIds(ids, snapshots = []){
    const live = _loreCatalogCache?.flat || [];
    const byId = new Map([...(Array.isArray(snapshots) ? snapshots : []), ...live].map((item) => [String(item.id), item]));
    return normalizePortableLoreBindings((ids || []).map((id) => {
      const item = byId.get(String(id));
      return item ? { book:item.book, entry:item.name } : null;
    }).filter(Boolean));
