  function scanNameHit(value, terms){
    const text = String(value || '').replace(/^(世界书:|角色书:)/, '').trim().toLowerCase();
    return terms.some((term) => text.includes(String(term).toLowerCase()));
  }
  function scannedLoreIds(books, bookNames, entryNames){
    const bookTerms = splitScanTerms(bookNames);
    const entryTerms = splitScanTerms(entryNames);
    const ids = new Set();
    (books || []).forEach((book) => {
      const wholeBook = bookTerms.length && scanNameHit(book.label || book.key, bookTerms);
      (book.entries || []).forEach((item) => {
        if (item.disabled) return;
        if (wholeBook || (entryTerms.length && scanNameHit(item.name, entryTerms))) ids.add(String(item.id));
      });
    });
    return ids;
  }

