        const summary = document.getElementById('worldbookPresetSummary');
        if (summary) summary.textContent = `已扫描到 ${books.length} 本世界书 · 已启用条目 ${enabledCount}`;
        box.innerHTML = `
          <div class="lore-empty" style="padding:6px 4px 10px;text-align:left">
            已扫描到 ${books.length} 本世界书 · 共 ${flat.length} 条 · 已启用条目 ${enabledCount}${!document.getElementById('setIncludeBg')?.checked && totalSel ? `（保留已选 ${totalSel}）` : ''}<br>
            点进某一本再勾选条目
          </div>` + books.map((b) => {
          const enabledEntries = b.entries.filter((e) => !e.disabled);
          const nSel = b.entries.filter((e) => _lorePickPending.has(e.id)).length;
          return `<div class="lore-book-row" data-lore-book="${esc(b.key)}">
            <div class="meta">
              <div class="nm">${esc(b.label)}</div>
              <div class="bk">可用 ${enabledEntries.length}/${b.entries.length} 条 · 已选 ${nSel}</div>
            </div>
            <div class="book-bulk"><button type="button" class="primary" data-lore-bulk="select" data-lore-book-key="${esc(b.key)}">整本勾选</button><button type="button" data-lore-bulk="clear" data-lore-book-key="${esc(b.key)}">取消</button></div>
            <div class="chev">›</div>
          </div>`;
        }).join('');
        bindLorePickListEvents(box);
        return;
      }

      // —— 第二层：某本书的条目（order 降序） ——
      const book = books.find((b) => b.key === _lorePickBookKey);
      if (!book) {
        _lorePickBookKey = null;
        return renderLorePickList(false);
      }
      const entries = book.entries.slice(); // 已按 order 降序
      box.innerHTML = `
        <div class="lore-pick-nav">
          <button type="button" class="back" data-lore-back>‹ 世界书</button>
          <div class="tt">${esc(book.label)}</div>
        </div>
        <div class="lore-empty" style="padding:4px 2px 8px;text-align:left">${entries.length} 条 · 按 order 降序</div>
        ${entries.map((item) => `
          <label class="lore-pick-item"${item.disabled ? ' style="opacity:.78"' : ''}>
            <input type="checkbox" data-lore-id="${esc(item.id)}" ${_lorePickPending.has(item.id) ? 'checked' : ''} />
            <div class="meta">
              <div class="nm">${esc(loreDisplayName(item))}</div>
              <div class="bk">order ${esc(String(item.order))}${item.keys?.length ? ' · ' + esc(item.keys.slice(0, 4).join(', ')) : ''}</div>
              <div class="pv">${esc(item.preview)}${(item.content || '').length > 120 ? '…' : ''}</div>
            </div>
          </label>`).join('')}
      `;
      bindLorePickListEvents(box);
    } catch (e) {
      box.innerHTML = '<div class="lore-empty">读取失败：' + esc(String(e && e.message || e)) + '</div>';
    }
  }
  function collectCheckedLorePicks(){
    syncLorePendingFromDom();
    const ids = [..._lorePickPending];
    const catalog = _loreCatalogCache?.flat || [];
    const byId = new Map(catalog.map((x) => [x.id, x]));
    const snap = ids.map((id) => {
      const hit = byId.get(id);
      if (hit) return { id: hit.id, book: hit.book, name: hit.name, content: hit.content };
      const old = (state.selectedLoreSnap || []).find((x) => x.id === id);
      return old || { id, book: '', name: id, content: '' };
    }).filter((x) => x.content);
    return { ids, snap };
  }
  function extractWbLoreBlocks(raw){
    const out = [];
    const re = /<wb_lore>([\s\S]*?)<\/wb_lore>/gi;
    let m;
    while ((m = re.exec(String(raw || '')))) {
      const t = String(m[1] || '').trim();
      if (t) out.push(t);
    }
    return out;
  }
  function joinWbLoreChunks(chunks){
    const seen = new Set();
    const out = [];
    (chunks || []).forEach((c) => {
      const t = String(c || '').trim();
      if (!t || seen.has(t)) return;
      seen.add(t);
      out.push(t);
    });
    return out.join('\n\n');
  }
  const DEFAULT_LORE_SECTION_TITLES = ['微博撰写要求', '其它初始化'];
  /** 把 wb_lore 拆成：账号字段 +【分节】+ 其它正文 */
  function parseWbLoreEditorModel(raw){
    let text = String(raw || '').replace(/\r\n/g, '\n').trim();
    const account = extractAccountInitFromLore(text) || {
      userId: '', charId: '', userFans: 0, charFans: 0,
      userFollowing: -1, charFollowing: -1, hit: false,
    };
    text = text.replace(/\[\s*账号\s*\|[^\]]*\]/gi, '').trim();
    const markers = [];
    const reM = /【([^】]+)】/g;
    let m;
    while ((m = reM.exec(text))) {
      markers.push({ title: String(m[1] || '').trim(), start: m.index, end: m.index + m[0].length });
    }
    const sections = [];
    let rest = '';
    if (!markers.length) {
      rest = text;
    } else {
      rest = text.slice(0, markers[0].start).trim();
      for (let i = 0; i < markers.length; i++) {
        const bodyStart = markers[i].end;
        const bodyEnd = i + 1 < markers.length ? markers[i + 1].start : text.length;
        sections.push({
          title: markers[i].title || ('分节' + (i + 1)),
          body: text.slice(bodyStart, bodyEnd).trim(),
        });
      }
    }
    // 保证常用标题有空壳，方便手填
    DEFAULT_LORE_SECTION_TITLES.forEach((title) => {
      if (!sections.some((s) => s.title === title)) sections.push({ title, body: '' });
    });
    return { account, sections, rest };
  }
  function readLoreAccountFromSettingsForm(){
    return {
      userId: (document.getElementById('setUserId')?.value || '').trim(),
      charId: (document.getElementById('setCharId')?.value || '').trim(),
      userFans: parseFanNumber(document.getElementById('setUserFans')?.value),
      charFans: parseFanNumber(document.getElementById('setCharFans')?.value),
      userFollowing: parseFanNumber(document.getElementById('setUserFollowing')?.value),
      charFollowing: parseFanNumber(document.getElementById('setCharFollowing')?.value),
    };
  }
  function applyLoreAccountToSettingsForm(account, opts={}){
    if (!account) return;
    const force = !!opts.force;
    const setIf = (id, val, asFan) => {
      const el = document.getElementById(id);
      if (!el) return;
      if (!force && String(el.value || '').trim()) return;
      if (val == null || val === '' || (typeof val === 'number' && val < 0)) return;
      el.value = asFan ? formatFanNumber(val) : String(val);
    };
    if (account.userId) setIf('setUserId', account.userId, false);
    if (account.charId) setIf('setCharId', account.charId, false);
    if (account.userFans > 0) setIf('setUserFans', account.userFans, true);
    if (account.charFans > 0) setIf('setCharFans', account.charFans, true);
    if (account.userFollowing >= 0) setIf('setUserFollowing', account.userFollowing, false);
    if (account.charFollowing >= 0) setIf('setCharFollowing', account.charFollowing, false);
  }
  function renderLoreSectionEditors(sections){
    const box = document.getElementById('loreSecList');
    if (!box) return;
    const list = (sections && sections.length) ? sections : DEFAULT_LORE_SECTION_TITLES.map((t) => ({ title: t, body: '' }));
    box.innerHTML = list.map((s, i) => `
      <div class="set-row" data-lore-sec="${i}">
        <label>【${esc(s.title)}】</label>
