  function composeWbLoreFromEditor(){
    const acc = readLoreAccountFromSettingsForm();
    const sections = readLoreSectionsFromDom();
    const rest = String(document.getElementById('loreRestText')?.value || '').trim();
    const lines = [];
    lines.push(`[账号|user|${acc.userId || ''}|粉丝:${formatFanNumber(acc.userFans || 0)}|关注:${acc.userFollowing || 0}]`);
    lines.push(`[账号|char|${acc.charId || ''}|粉丝:${formatFanNumber(acc.charFans || 0)}|关注:${acc.charFollowing || 0}]`);
    if (rest) lines.push(rest);
    sections.forEach((s) => {
      if (!s.body) return;
      lines.push(`【${s.title}】`);
      lines.push(s.body);
    });
    return lines.join('\n').trim();
  }
  function cleanWbLoreEditorText(raw){
    let text = String(raw || '').trim().replace(/^\[微博档位\|[^\]]*\]\s*/i, '');
    const prompts = chatSlots().map((slot) => String(slot?.initPrompt || '').trim()).filter(Boolean).sort((a, b) => b.length - a.length);
    for (const prompt of prompts) {
      const prefix = '[初始化提示词]\n' + prompt;
      if (text.startsWith(prefix)) { text = text.slice(prefix.length).trim(); break; }
    }
    return text;
  }
  function fillWbLoreEditor(raw, opts={}){
    const cleaned = cleanWbLoreEditorText(raw);
    const model = parseWbLoreEditorModel(cleaned);
    applyLoreAccountToSettingsForm(model.account, { force: !!opts.forceAccount });
    renderLoreSectionEditors(model.sections);
    const restEl = document.getElementById('loreRestText');
    if (restEl) restEl.value = model.rest || '';
    const rawEl = document.getElementById('loreRawText');
    if (rawEl) rawEl.value = cleaned;
    return model;
  }
  /** wb_lore 的楼层唯一来源是当前聊天首楼，不再扫描旧楼/前楼层。 */
  function readFirstFloorWbLoreFromChat(){
    const stripLauncherEnvelope = (text) => {
      let out = String(text || '').trim().replace(/^\[微博档位\|[^\]]*\]\s*/i, '');
      const prompts = chatSlots().map((slot) => String(slot?.initPrompt || '').trim()).filter(Boolean).sort((a, b) => b.length - a.length);
      for (const prompt of prompts) {
        const prefix = '[初始化提示词]\n' + prompt;
        if (out.startsWith(prefix)) { out = out.slice(prefix.length).trim(); break; }
      }
      return out;
    };
    const pickFirst = (list) => {
      if (!Array.isArray(list) || !list.length) return '';
      return stripLauncherEnvelope(joinWbLoreChunks(extractWbLoreBlocks(extractRawMessageText(list[0]))));
    };
    try { return pickFirst(readFullChatMessageList()); } catch (_) {}
    return '';
  }
