      if (text) ctx.chatMetadata.weibo_wb_lore = text;
      else delete ctx.chatMetadata.weibo_wb_lore;
      if (typeof ctx.saveMetadata === 'function') await ctx.saveMetadata();
      else if (typeof saveMetadata === 'function') await saveMetadata();
