    if (state.wbLore && !force) {
      if (!state.fansFromStore) applyFansFromWbLore(state.wbLore);
      return state.wbLore;
    }

    let found = '';
    // 1) 主存：本聊天 metadata（与楼层无关）
    found = readChatMetadataLore() || String(readPhoneBundleFromMetadata()?.wbLore || '').trim();
    // 2) 同浏览器 localStorage；首楼仅可在设置中手动「从首楼读取」覆盖。
    if (!found) {
