        found = String(all[phoneDataBucketId()]?.wbLore || '').trim();
      } catch (_) {}
    }
    if (found) await persistWbLore(found);
    else if (force) await persistWbLore('');
    else if (!state.fansFromStore) applyFansFromWbLore(state.wbLore);
    return state.wbLore || '';
