  function loadPhoneData(){
    try {
      const all = JSON.parse(localStorage.getItem(PHONE_DATA_KEY) || '{}');
      const hit = all[phoneDataBucketId()];
      if (!hit) return false;
      if (Array.isArray(hit.posts)) state.posts = hit.posts;
