      if (hit.wbLore) state.wbLore = String(hit.wbLore);
      if (Array.isArray(hit.selectedLoreIds)) state.selectedLoreIds = hit.selectedLoreIds.map(String);
      if (Array.isArray(hit.selectedLoreSnap)) state.selectedLoreSnap = hit.selectedLoreSnap;
      state.loreAutoSuppressed = !!hit.loreAutoSuppressed;
      const uf = Number(hit.userFans);
      const cf = Number(hit.charFans);
      if (Number.isFinite(uf) && uf > 0) { state.userFans = uf; state.fansFromStore = true; }
      if (Number.isFinite(cf) && cf > 0) { state.charFans = cf; state.fansFromStore = true; }
      const ufo = Number(hit.userFollowing);
      const cfo = Number(hit.charFollowing);
      if (Number.isFinite(ufo) && ufo >= 0) state.userFollowing = ufo;
      if (Number.isFinite(cfo) && cfo >= 0) state.charFollowing = cfo;
      return !!(state.posts.length || state.threads.length || state.wbLore || state.selectedLoreIds.length || state.userFans || state.charFans);
