  /**
   * 小微博专用上下文（精简）。
   * 依据左宥之卡结构：
   * - 开场白仅在用户开启时独立注入；只认当前聊天第 1 楼，禁止从 alternate_greetings 乱挑
   * - 角色书里「微博热搜输出」「脆文输出」「UpdateVariable」会抢格式，禁止整本灌进手机 prompt
   * - 只保留：人设摘要、可选开场、柏宝书历史摘要、近期完整聊天、知情范围与微博协议世界书
   */
  async function collectStContextSnapshot(maxMsgs = 3, maxChars = 14000, scanKeyword = '', nativePartsOverride = null){
    maxMsgs = Math.max(0, Math.min(60, Number(phoneSettings.recentMessages ?? maxMsgs) || 0));
    _lastMainLoreClaimKeys = new Set();
    const historyContext = normalizeHistoryContext({ ...phoneSettings, mode:phoneSettings.contextMode });
    const chunks = [];
    const push = (title, text) => {
      const t = String(text || '').trim();
      if (!t) return;
      chunks.push('### ' + title + '\n' + t);
    };

    const slot = currentSlot();
    if (slot?.initPrompt) push('当前微博档位初始化提示词（最高优先级）', String(slot.initPrompt).slice(0, 8000));

    // 钉住设定优先：跟微博楼层 / chatMetadata，不依赖开场是否还在前文
    try {
      await harvestWbLore();
      if (state.wbLore) {
        push('小微博钉住设定（wb_lore｜不受隐藏前文影响）', String(state.wbLore).slice(0, 8000));
      }
    } catch (_) {}

    // 自定义条目会在请求阶段按各自 depth 独立注入，不在快照中重复合并。

    const _ejsOpen = '<' + '%';
    const _ejsClose = '%' + '>';
    const _ejsBlockRe = new RegExp(_ejsOpen.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[\\s\\S]*?' + _ejsClose.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    const clip = (s, n) => {
      s = String(s || '')
        .replace(_ejsBlockRe, '[ejs已省略]')
        .split(_ejsOpen).join('<\uFF05')
        .split(_ejsClose).join('\uFF05>');
      return s.length > n ? s.slice(0, n) + '…[截断]' : s;
    };
    // 供手机阅读的楼层清洗：去掉界面 HTML / 协议壳 / 变量块，保留剧情与开场正文
    const cleanFloorText = (raw) => {
      let s = String(raw || '');
      const loreChunks = [];
      s = s.replace(/<wb_lore>([\s\S]*?)<\/wb_lore>/gi, (_, inner) => {
        const t = String(inner || '').trim();
        if (t) loreChunks.push(t);
        return '\n';
      });
      // 某些正文 CoT 会把草稿/审核都放在 HTML 注释里，只把最终正文包进 <content>。
      // 若检测到 content 容器，只读取最后一个容器；后续再移除其中的 draft/audit/锚定注释。
      const contentBlocks = [...s.matchAll(/<content(?:\s[^>]*)?>([\s\S]*?)<\/content>/gi)];
      if (contentBlocks.length) s = String(contentBlocks[contentBlocks.length - 1][1] || '');
      // 柏宝书的正文时间标签保留时间语义，但转成普通文本，避免把插件协议标签交给微博模型。
      s = s.replace(/<bbs_start(?:\s[^>]*)?>([\s\S]*?)<\/bbs_start>/gi, (_, t) => `(起始时间:${String(t || '').trim()})`)
        .replace(/<bbs_end(?:\s[^>]*)?>([\s\S]*?)<\/bbs_end>/gi, (_, t) => `(结束时间:${String(t || '').trim()})`);
      s = s.replace(/<script[\s\S]*?<\/script>/gi, '');
      s = s.replace(/```html[\s\S]*?```/gi, '[界面已省略]');
      s = s.replace(/```[\s\S]*?```/g, '');
      s = s.replace(/<weiboapp>[\s\S]*?<\/weiboapp>/gi, '[小微博界面已省略]');
      s = s.replace(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi, '');
      s = s.replace(/<JSONPatch>[\s\S]*?<\/JSONPatch>/gi, '');
      s = s.replace(/<!--[\s\S]*?-->/g, '');
      // 大段 HTML 标签压成空白，保留可见文案
      if (/<\/?[a-z][\s\S]*>/i.test(s) && s.length > 800) {
        s = s.replace(/<style[\s\S]*?<\/style>/gi, '')
          .replace(/<[^>]+>/g, ' ')
          .replace(/&nbsp;/g, ' ')
          .replace(/[ \t]+\n/g, '\n')
          .replace(/\n{3,}/g, '\n\n')
          .replace(/[ \t]{2,}/g, ' ');
      }
      s = s.trim();
      if (loreChunks.length) {
        s = (s ? s + '\n\n' : '') + '【开场隐藏设定 wb_lore】\n' + loreChunks.join('\n\n');
      }
      return s.trim();
    };
    const isJunkLore = (name, keys, content) => {
      const blob = (String(name||'') + ' ' + (keys||[]).join(' ') + ' ' + String(content||'').slice(0, 500)).toLowerCase();
      if (/updatevariable|jsonpatch|format_message_variable|mvu_update|status_current_variable/.test(blob)) return true;
      if (/wb-root|doctype|模拟微博手机|脆文输出|threads|热搜输出/.test(blob)) return true;
      if (/initvar|不要关|脚本内容读取/.test(String(name||''))) return true;
      if (/writing_spec|forbidden_narrative|nsfw_information/.test(blob) && !/知情范围/.test(blob)) return true;
      return false;
    };
    let openingHaystack = ''; // 本局开场文本，用于让「非微博专用」条目按关键词自动对上当前世界线

    const isUsefulLore = (name, keys, content, kw, isConst) => {
      const n = String(name || '');
      const keyList = (keys || []).map((x) => String(x || '').trim()).filter(Boolean);
      const keyStr = keyList.join(',').toLowerCase();
      const c = String(content || '');
      if (isJunkLore(n, keyList, c)) return false;

      if (/知情范围|小微博|推荐页拉取|微博路人/.test(n + c.slice(0, 200))) return true;
      if (kw && (keyStr.includes(kw) || c.toLowerCase().includes(kw))) {
        if (c.length < 3500) return true;
      }

      // 关键：条目关键词出现在「本局开场」里 → 视为当前世界线素材（不必是纯微博条目）
      if (openingHaystack) {
        const hay = openingHaystack.toLowerCase();
        for (const k of keyList) {
          const kk = k.toLowerCase();
          if (kk.length < 2) continue;
          // 路由旗标 / 开场标题 / 独特专名
          if (hay.includes(kk) && c.length < 6000) return true;
        }
        // 名称里带线路标记且开场也有（如 嫂子梗3、布鲁克林、助理线）
        const nameHit = n.match(/嫂子梗\d?|布鲁克林|助理线|前女友|小演员|网黄|私生女|伪骨科|on left hand|冲水按钮/i);
        if (nameHit && hay.includes(String(nameHit[0]).toLowerCase()) && c.length < 6000) return true;
      }

      // 已开启背景条目（设置开关，默认开；未手动勾选时生效）
      if (phoneSettings.includeBgLore !== false) {
        if (/world_setting|世界观|背景设定|名利场|娱乐圈|家族/.test(n + c.slice(0, 400))) {
          return c.length < 9000;
        }
        if (isConst && c.length > 200 && c.length < 7000
          && !/好感度|阶段设定|变量|mvu|initvar|writing_spec|nsfw/i.test(n)
          && !/associated_variable|JSONPatch|UpdateVariable/i.test(c.slice(0, 600))) {
          return true;
        }
      }
      return false;
    };

    let ctx = null;
    try {
      ctx = (typeof SillyTavern !== 'undefined' && SillyTavern.getContext)
        ? SillyTavern.getContext()
        : (window.parent && window.parent.SillyTavern && window.parent.SillyTavern.getContext)
          ? window.parent.SillyTavern.getContext()
          : null;
    } catch (_) {}

    // —— 人设摘要（短）——
    try {
      if (ctx) {
        const charId = ctx.characterId;
        const ch = (ctx.characters && charId != null) ? ctx.characters[charId] : null;
        const data = ch?.data || ch || {};
        // description 太长只留身份/关系相关头一段
        if (phoneSettings.includeChar !== false) {
          push('角色名', ch?.name || data.name || displayChar || charName);
          push('角色摘要 description', clip(data.description || ch?.description || '', 2200));
          if (data.personality || ch?.personality) push('性格', clip(data.personality || ch.personality, 800));
        }
        if (phoneSettings.includeScenario !== false && (data.scenario || ch?.scenario)) push('场景', clip(data.scenario || ch.scenario, 800));
        if (phoneSettings.includePersona !== false) {
          const persona = ctx?.powerUserSettings?.persona_description || ctx?.powerUserSettings?.persona || '';
          if (ctx.name1) push('用户显示名', String(ctx.name1));
          if (persona) push('用户 Persona', clip(persona, 1400));
        }

        // 开场白只取当前聊天首楼，避免卡面 first_mes / 备用开场污染本局。
      }
    } catch (e) {
      push('角色卡读取异常', String(e && e.message || e));
    }

    if (historyContext.includeBaiBaiHistory) {
      const parts = nativePartsOverride || buildBaiBaiNativeRequestParts(ctx);
      if (parts.history.text) push('柏宝书历史剧情摘要', parts.history.text);
