  function isMacro(v){ return !v || /\{\{/.test(String(v)); }
  function stOrigin(){
    const o = (window.location && window.location.origin) ? String(window.location.origin) : '';
    if (o && o !== 'null') return o.replace(/\/+$/, '');
    try {
      const p = window.parent?.location?.origin;
      if (p && p !== 'null') return String(p).replace(/\/+$/, '');
    } catch (_) {}
    return 'http://127.0.0.1:8000';
  }
  function resolveAvatarUrl(raw){
    let v = String(raw || '').trim();
    if (!v || isMacro(v)) return '';
    if (/^IMGDATA:/i.test(v) || v.includes('IMGDATA:')) {
      const parts = v.split('|');
      for (const part of parts) {
        const p = String(part || '').trim();
        if (/^IMGDATA:/i.test(p)) { v = p.slice(8).trim(); break; }
      }
    }
    if (/^https?:\/\//i.test(v) || v.startsWith('data:')) return v;
    // 去 ./ 前缀
    v = v.replace(/^\.\//, '');
    // 酒馆本地头像目录（用户 / 角色）
    if (/^User Avatars\//i.test(v) || /^useravatars\//i.test(v) || /^characters\//i.test(v) || /^thumbnails\//i.test(v)) {
      return stOrigin() + '/' + v.split('/').map((seg) => encodeURIComponent(seg)).join('/');
    }
    if (v.startsWith('/')) return stOrigin() + v;
    // 仅纯文件名时，优先当作用户头像目录，而不是 catbox
    const file = v.match(/^([a-zA-Z0-9._-]+\.(?:jpe?g|png|gif|webp|bmp))$/i);
    if (file) {
      // 常见：宏给出裸文件名 → User Avatars
      return stOrigin() + '/User%20Avatars/' + encodeURIComponent(file[1]);
    }
    // 含路径但未匹配上面：拼到 origin
    if (v.includes('/') || v.includes('\\')) {
      const norm = v.replace(/\\/g, '/');
      return stOrigin() + '/' + norm.split('/').map((seg) => encodeURIComponent(seg)).join('/');
    }
    return v;
  }
  function peekCtxUserAvatar(){
    try {
      const ctx = (typeof SillyTavern !== 'undefined' && SillyTavern.getContext)
