  function tokenMeansUser(token){
    const t = String(token || '').trim().toLowerCase();
    return t === 'user' || t === 'user.png' || t === '{{useravatarpath}}' || t === String(userAvatarPath || '').trim().toLowerCase();
  }
  function uniqNames(list){
    const out = [];
    const seen = new Set();
    (list || []).forEach((v) => {
      const s = String(v ?? '').trim();
      if (!s || /\{\{/.test(s) || seen.has(s)) return;
      seen.add(s);
      out.push(s);
    });
    return out;
  }
  function collectUserNameCandidates(){
    const names = [
      rawUserName,
      userName,
      displayName,
      phoneSettings.userWeiboId,
      '我',
      ...(phoneSettings.userAliases || []),
    ];
    (state.posts || []).forEach((p) => {
      if (tokenMeansUser(p.avatar) || isUserAuthor(p.author)) names.push(p.author);
      (p.comments || []).forEach((c) => {
        if (isUserAuthor(c.author)) names.push(c.author);
        if (c.replyTo && isUserAuthor(c.replyTo)) names.push(c.replyTo);
