    return uniqNames(names);
  }
  function collectCharNameCandidates(){
    const names = [
      rawCharName,
      charName,
      displayChar,
      phoneSettings.charWeiboId,
      ...(phoneSettings.charAliases || []),
    ];
    (state.posts || []).forEach((p) => {
      if (tokenMeansChar(p.avatar) || isCharAuthor(p.author)) names.push(p.author);
      (p.comments || []).forEach((c) => {
        if (isCharAuthor(c.author)) names.push(c.author);
        if (c.replyTo && isCharAuthor(c.replyTo)) names.push(c.replyTo);
      });
