  function isUserAuthor(name){
    const n = String(name || '').trim();
    if (!n || n === '我' || n === '我方消息') return true;
    if (n === displayName || n === rawUserName || (userName && n === String(userName))) return true;
    return (phoneSettings.userAliases || []).includes(n);
  }
  function isCharAuthor(name){
    const n = String(name || '').trim();
    if (!n) return false;
    if ((displayChar && n === displayChar) || (rawCharName && n === rawCharName)) return true;
    if (charName && n === String(charName) && !/\{\{/.test(String(charName))) return true;
