  }
  /** 保存新昵称时：把历史里属于 user/char 的作者名、replyTo、相关线程名全部改成新昵称 */
  function remapIdentityNames(kind, fromNames, toName){
    toName = String(toName || '').trim();
    if (!toName) return 0;
    const from = new Set(uniqNames(fromNames));
    from.delete(toName);
    const hit = (name) => from.has(String(name || '').trim());
    let n = 0;

    (state.posts || []).forEach((p) => {
      const byAvatar = kind === 'user' ? tokenMeansUser(p.avatar) : tokenMeansChar(p.avatar);
      if (hit(p.author) || byAvatar) {
        if (p.author !== toName) { p.author = toName; n++; }
        p.avatar = kind === 'user' ? defaultUserAvatarToken() : defaultCharAvatarToken();
      }
      (p.comments || []).forEach((c) => {
        if (hit(c.author)) { c.author = toName; n++; }
        if (c.replyTo && hit(c.replyTo)) { c.replyTo = toName; n++; }
      });
    });

    (state.threads || []).forEach((t) => {
      if (kind === 'char' && hit(t.name)) {
        t.name = toName;
        n++;
      }
      (t.messages || []).forEach((m) => {
        if (kind === 'user') {
          // 用户私信用 sender=user，不依赖昵称；若旧数据误写了用户名则纠正
          if (m.sender === 'user') return;
          if (hit(m.author)) {
            m.sender = 'user';
            delete m.author;
            n++;
          }
        } else if (kind === 'char') {
          if (m.sender === 'user') return;
          if (hit(m.author)) {
            m.author = toName;
            m.avatar = defaultCharAvatarToken();
            n++;
          }
        }
      });
    });
    return n;
  }
  function rememberNameAliases(kind, fromNames, currentName){
    const key = kind === 'user' ? 'userAliases' : 'charAliases';
