  function avatarInner(name, token){
    const n = String(name || '').trim();
    let url = '';
    if (tokenMeansUser(token) || (!token && isUserAuthor(n))) url = getUserAvatarUrl();
    else if (tokenMeansChar(token) || isCharAuthor(n)) url = getCharAvatarUrl(n || displayChar);
    else url = resolveAvatarUrl(token);
    if (!url && isUserAuthor(n)) url = getUserAvatarUrl();
    if (!url && isCharAuthor(n)) url = getCharAvatarUrl(n);
