  // ---- protocol ----
  function serializeWeiboApp(){
    ensureProfileStats();
    const lines=['<weiboapp>'];
    const meta = {
      postsUnread: (state.posts || []).map((p) => Number(p.unread) || 0),
      postVisibility: (state.posts || []).map((p) => visibilitySpec(p)),
      threadsUnread: {},
      selectedLoreIds: readSelectedLoreIds(),
      userFans: Number(state.userFans) || 0,
      charFans: Number(state.charFans) || 0,
      userFollowing: Number(state.userFollowing) || 0,
      charFollowing: Number(state.charFollowing) || 0,
    };
    (state.threads || []).forEach((t) => {
      const u = Number(t.unread) || 0;
      if (u > 0) meta.threadsUnread[t.name] = u;
    });
    lines.push('<!--wb_ui:' + JSON.stringify(meta) + '-->');
    // 明文账号行：楼层里肉眼可见，也方便回溯
    lines.push(`[账号|user|${displayName}|粉丝:${formatFanNumber(state.userFans)}|关注:${Number(state.userFollowing)||0}]`);
    lines.push(`[账号|char|${displayChar || rawCharName || 'char'}|粉丝:${formatFanNumber(state.charFans)}|关注:${Number(state.charFollowing)||0}]`);
    // 仅「已确认来自 lore/设置/主存」才锁死；随机兜底粉量不锁，免得挡开场 [账号]
    if (state.wbLore) {
      lines.push('<wb_lore>');
      lines.push(String(state.wbLore).trim());
      lines.push('</wb_lore>');
    }
    if ((state.selectedLoreSnap || []).length) {
      // 正文快照钉在楼层里：隐藏前文 / 世界书临时读失败也能用
      const slim = state.selectedLoreSnap.map((x) => ({
        id: x.id,
        book: x.book,
        name: x.name,
        content: String(x.content || '').slice(0, 6000),
      }));
      lines.push('<!--wb_lore_pick:' + JSON.stringify(slim) + '-->');
    }
    lines.push('<weibo>');
    state.posts.forEach((p,i)=>{
      const n=i+1;
      ensurePostEngagement(p);
      lines.push(`<post:${n}>`);
      lines.push(`[微博|${p.author}|${p.avatar||defaultUserAvatarToken()}|${p.text}|${p.time}|${p.likes||0}|${p.reposts||0}|${p.commentCount||0}]`);
      if(p.fakeImage) lines.push(`[伪图|${p.fakeImage}]`);
      (p.comments||[]).forEach(c=>{
        scrubComment(c);
        if(c.replyTo && !looksLikeAvatarToken(c.replyTo)) lines.push(`[评论|${c.author}|${c.replyTo}|${c.text}|${c.time}]`);
        else lines.push(`[评论|${c.author}|${c.text}|${c.time}]`);
      });
      lines.push(`</post:${n}>`);
    });
    // 私信箱：用 <msg>/<chat:>（微博消息会话）。旧 <dm>/<thread:> 仅解析兼容，不再写出。
    lines.push('</weibo>','<msg>');
    state.threads.forEach(t=>{
      lines.push(`<chat:${t.name}>`);
      (t.messages||[]).forEach(m=>{
        if(m.sender==='user') lines.push(`[私信|我方消息|${m.text}|${m.time}]`);
        else if(m.type==='分享' || m.type==='share') { const shared=resolveSharedPost(m); if(shared) lines.push(`[分享微博|post:${shared.index+1}|${m.text||'分享了一条微博'}|${m.time}]`); }
        else lines.push(`[私信|${m.author}|${m.avatar||'npc.png'}|${m.text}|${m.time}]`);
      });
      lines.push(`</chat:${t.name}>`);
    });
    lines.push('</msg>','</weiboapp>');
    return lines.join('\n');
  }
  function parseFanNumber(raw){
    let s = String(raw == null ? '' : raw).trim();
    if (!s) return 0;
    s = s.replace(/,/g, '').replace(/，/g, '').replace(/\s+/g, '');
    // 1087万 / 1.2亿 / 387 / 12k
    const m = s.match(/^(\d+(?:\.\d+)?)(万|亿|w|W|k|K)?/);
    if (!m) {
      const n = parseInt(s, 10);
      return Number.isFinite(n) && n > 0 ? n : 0;
    }
    let n = parseFloat(m[1]);
    if (!Number.isFinite(n)) return 0;
    const unit = m[2] || '';
    if (unit === '万' || unit === 'w' || unit === 'W') n *= 10000;
    else if (unit === '亿') n *= 1e8;
    else if (unit === 'k' || unit === 'K') n *= 1000;
    return Math.max(0, Math.round(n));
  }
  function formatFanNumber(n){
    n = Number(n) || 0;
    if (n >= 1e8) {
      const v = n / 1e8;
      return (v >= 10 ? String(Math.round(v)) : String(Math.round(v * 10) / 10)) + '亿';
    }
    if (n >= 10000) {
      const v = n / 10000;
      return (v >= 100 ? String(Math.round(v)) : String(Math.round(v * 10) / 10)) + '万';
    }
    return String(n);
  }
  /** 解析 [账号|user|昵称|粉丝:…|关注:…] */
  function extractAccountInitFromLore(raw){
    const text = String(raw || '');
    if (!text.trim()) return null;
    const out = {
      userId: '', charId: '',
      userFans: 0, charFans: 0,
      userFollowing: -1, charFollowing: -1,
      hit: false,
    };
    const reAcc = /\[\s*账号\s*\|\s*(user|char)\s*\|([^|\]]*)\|\s*粉丝\s*[:：]?\s*([^|\]]*)\|\s*关注\s*[:：]?\s*([^|\]]*)\s*\]/gi;
    let m;
    while ((m = reAcc.exec(text))) {
      const who = String(m[1] || '').toLowerCase();
      const id = String(m[2] || '').trim();
      const fans = parseFanNumber(m[3]);
      const following = parseFanNumber(m[4]);
      out.hit = true;
      if (who === 'user') {
        if (id) out.userId = id;
        if (fans > 0) out.userFans = fans;
        if (following >= 0) out.userFollowing = following;
      } else if (who === 'char') {
        if (id) out.charId = id;
        if (fans > 0) out.charFans = fans;
        if (following >= 0) out.charFollowing = following;
      }
    }
    // 自然语言粉丝（可带万）
    const nat = [
      { who: 'user', re: /(?:user|我|玩家)\s*(?:的)?\s*粉丝(?:数)?\s*[:：]?\s*([0-9.]+)\s*(万|亿|w|W|k|K)?/gi },
      { who: 'char', re: /(?:char|角色|卡)\s*(?:的)?\s*粉丝(?:数)?\s*[:：]?\s*([0-9.]+)\s*(万|亿|w|W|k|K)?/gi },
    ];
    nat.forEach(({ who, re }) => {
      let mm;
      while ((mm = re.exec(text))) {
        const fans = parseFanNumber(mm[1] + (mm[2] || ''));
        if (!(fans > 0)) continue;
        out.hit = true;
        if (who === 'user') out.userFans = fans;
        else out.charFans = fans;
      }
    });
    const reFanTag = /\[\s*粉丝\s*\|\s*(user|char)\s*\|\s*([^|\]]+)\s*\]/gi;
    while ((m = reFanTag.exec(text))) {
      const who = String(m[1] || '').toLowerCase();
      const fans = parseFanNumber(m[2]);
      if (!(fans > 0)) continue;
      out.hit = true;
      if (who === 'user') out.userFans = fans;
      else if (who === 'char') out.charFans = fans;
    }
    return out.hit ? out : null;
  }
  function parseAccountStatsFromText(raw){
    const hit = extractAccountInitFromLore(raw);
    if (!hit) return;
    if (hit.userFans > 0) { state.userFans = hit.userFans; state.fansFromStore = true; }
    if (hit.charFans > 0) { state.charFans = hit.charFans; state.fansFromStore = true; }
    if (hit.userFollowing >= 0) state.userFollowing = hit.userFollowing;
    if (hit.charFollowing >= 0) state.charFollowing = hit.charFollowing;
  }
  function extractFansFromLoreText(raw){
    return extractAccountInitFromLore(raw);
  }
  /** 从 wb_lore 初始化粉丝 + 微博昵称（id） */
  function applyFansFromWbLore(raw, opts={}){
    const hit = extractAccountInitFromLore(raw == null ? state.wbLore : raw);
    if (!hit) return false;
    const force = !!opts.force;
    let changed = false;

    // 粉/关注：未锁死或 force 时写入
    if (force || !state.fansFromStore) {
      if (hit.userFans > 0) { state.userFans = hit.userFans; changed = true; }
      if (hit.charFans > 0) { state.charFans = hit.charFans; changed = true; }
      if (hit.userFollowing >= 0) { state.userFollowing = hit.userFollowing; changed = true; }
      if (hit.charFollowing >= 0) { state.charFollowing = hit.charFollowing; changed = true; }
      if (changed) state.fansFromStore = true;
    }

    // 昵称/id：force，或设置里还空时，用 lore 账号行（与粉量锁死无关，避免「粉随机锁死后 id 永远抓不到」）
    const nextSettings = {};
    if (hit.userId && (force || !(phoneSettings.userWeiboId || '').trim())) {
      nextSettings.userWeiboId = hit.userId;
    }
    if (hit.charId && (force || !(phoneSettings.charWeiboId || '').trim())) {
      nextSettings.charWeiboId = hit.charId;
    }
    if (Object.keys(nextSettings).length) {
      savePhoneSettings(nextSettings);
      changed = true;
    }
    return changed;
  }
  function parseWeiboApp(raw){
    const text=normalizeAiText(raw);
    // 先读楼层已存账号行 / wb_ui（二次及以后的真源）
    parseAccountStatsFromText(text);
    const uiMeta = extractUiMeta(text);
    if (uiMeta) applyUiMeta(uiMeta);
    // 仅当楼层还没有粉丝记录时，才用壳内 <wb_lore> 做第一次初始化
    if (!state.fansFromStore) {
      const loreBits = [];
      text.replace(/<wb_lore>([\s\S]*?)<\/wb_lore>/gi, (_, inner) => { loreBits.push(inner); return ''; });
      if (loreBits.length) applyFansFromWbLore(loreBits.join('\n'));
    }
    const posts=[], threads=[];
    let m;
    // 兼容 </post:1> / </post> / 编号不一致
    const postRe=/<post:(\d+)>([\s\S]*?)(?:<\/post:\d+>|<\/post>)/gi;
    while((m=postRe.exec(text))){
      const post={author:displayName,avatar:defaultUserAvatarToken(),text:'',time:today(),likes:0,reposts:0,fakeImage:'',comments:[]};
      String(m[2]).split(/\n/).map(l=>l.trim()).filter(Boolean).forEach(line=>{
        const wb=line.match(/^\[微博\|([^|]*)\|([^|]*)\|([\s\S]*?)\|([^|]*)\|([^\]]*)\]$/);
        if(wb){
          post.author=wb[1]; post.avatar=wb[2]; post.text=wb[3]; post.time=wb[4];
          // 兼容：…|赞数] / …|赞数|转发数] / …|赞数|转发数|评论数]
          const tail = String(wb[5] || '').split('|').map((x) => String(x).trim());
          post.likes = Number(tail[0]) || 0;
          post.reposts = Number(tail[1]) || 0;
          post.commentCount = Number(tail[2]) || 0;
          return;
        }
        const img=line.match(/^\[伪图\|([\s\S]*?)\]$/);
        if(img){ post.fakeImage=img[1]; return; }
      });
      post.comments = extractCommentsFromText(m[2]);
      if(post.text || post.comments.length) posts.push(post);
    }
    // 无 <post> 时：整段里的评论仍可抽出
    if(!posts.length){
      const orphan=extractCommentsFromText(text);
      if(orphan.length) posts.push({author:'',avatar:'',text:'',time:today(),likes:0,reposts:0,fakeImage:'',comments:orphan});
    }
    // 会话块：<chat:昵称>…</chat:昵称>（首选）；兼容旧 <thread:> / 中文 <会话:>
    const chatRe=/<(?:chat|thread|会话):([^>]+)>([\s\S]*?)(?:<\/(?:chat|thread|会话):\1>|<\/(?:chat|thread|会话)>)/gi;
    while((m=chatRe.exec(text))){
      const name=m[1].trim();
      if(!name) continue;
      threads.push({name, messages:extractDmFromText(m[2], name)});
    }
    if(!threads.length){
      // 无会话壳时：只从 <msg>/<dm>/<私信箱> 内抽 [私信|…]；再不行才扫全文
      let msgScope = '';
      const boxRe=/<(?:msg|dm|私信箱)>([\s\S]*?)<\/(?:msg|dm|私信箱)>/gi;
      let bm;
      while((bm=boxRe.exec(text))) msgScope += bm[1] + '\n';
      const loose=extractDmFromText(msgScope || text);
      const byName={};
      loose.forEach(msg=>{
        const n = msg.author || '路人';
        if(!byName[n]) byName[n]=[];
        byName[n].push(msg);
      });
      Object.keys(byName).forEach(n=>threads.push({name:n, messages:byName[n]}));
    }
    (uiMeta?.postVisibility || []).forEach((visibility, index) => { if (posts[index] && visibility) posts[index].visibility = visibility; });
    return {posts, threads};
  }

  function normalizeAiText(raw){
    let s = '';
    if (raw == null) s = '';
    else if (typeof raw === 'string') s = raw;
    else if (typeof raw === 'object') {
      if (typeof raw.content === 'string') s = raw.content;
      else if (typeof raw.message === 'string') s = raw.message;
      else if (typeof raw.text === 'string') s = raw.text;
      else if (typeof raw.result === 'string') s = raw.result;
      else if (Array.isArray(raw)) {
        s = raw.map((x) => {
          if (typeof x === 'string') return x;
          if (x && typeof x.content === 'string') return x.content;
          if (x && typeof x.text === 'string') return x.text;
          return '';
        }).join('');
      } else {
        try { s = JSON.stringify(raw); } catch (_) { s = String(raw); }
      }
    } else s = String(raw);

    s = s.replace(/\u｜/g, '|').replace(/｜/g, '|');
    s = s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
    s = s.replace(/```[\w-]*\n?([\s\S]*?)```/g, '$1');
    s = s.replace(/<think>[\s\S]*?<\/think>/gi, '');
    s = s.replace(/<\/?thinking>/gi, '');
    // 去掉协议块之前的英文思考/解释
    const proto = s.search(/<(?:weiboapp|weibo|msg|dm|私信箱|post:\d+|chat:|thread:|会话:)/i);
    if (proto > 0) s = s.slice(proto);
    return s;
  }

  function looksLikeAvatarToken(s){
    const t = String(s || '').trim();
    if (!t) return false;
    if (/^avatar[_\-]/i.test(t)) return true;
    if (/\.(png|jpe?g|gif|webp|svg|bmp)$/i.test(t)) return true;
    if (/^(char|user|npc)(\.(png|jpe?g|webp))?$/i.test(t)) return true;
    // 纯技术 token：无中文、较短、含 avatar/img 等
    if (!/[\u4e00-\u9fff]/.test(t) && /^[a-z0-9_\-.]{3,48}$/i.test(t) && /(avatar|img|icon|face|head|pic)/i.test(t)) {
      return true;
    }
    return false;
  }
  function looksLikeTimeToken(s){
    const t = String(s || '').trim();
    if (!t) return false;
    if (/刚刚|分钟前|小时前|昨天|前天|今天|周一|周二|周三|周四|周五|周六|周日/.test(t)) return true;
    if (/^\d{1,2}:\d{2}$/.test(t)) return true;
    if (/^\d{1,2}月\d{1,2}日/.test(t)) return true;
    if (/^(今天|昨天)\s*\d{1,2}:\d{2}/.test(t)) return true;
    return false;
  }
  /** 纠正 AI 误把头像字段写进评论协议导致的 replyTo=avatar_xxx */
  function scrubComment(c){
    if (!c || typeof c !== 'object') return c;
    if (looksLikeAvatarToken(c.replyTo)) {
      if (!c.avatar) c.avatar = c.replyTo;
      delete c.replyTo;
    }
    if (looksLikeAvatarToken(c.text) && c.replyTo && !looksLikeAvatarToken(c.replyTo)) {
      // 极少见错位：正文位是头像
      if (!c.avatar) c.avatar = c.text;
      c.text = c.replyTo;
      delete c.replyTo;
    }
    if (looksLikeAvatarToken(c.time)) {
      if (!c.avatar) c.avatar = c.time;
      c.time = nowHM();
    }
    // 正文里误嵌「回复 avatar_xxx」时清掉
    if (c.text && /回复\s*avatar[_\-]/i.test(c.text)) {
      c.text = String(c.text).replace(/\s*回复\s*avatar[_-][a-z0-9_\-.]*/ig, '').trim();
    }
    return c;
  }
  function scrubAllComments(){
    (state.posts || []).forEach((p) => {
      if (!Array.isArray(p.comments)) return;
      p.comments.forEach(scrubComment);
    });
  }
  function extractCommentsFromText(text){
    const comments=[];
    const src=normalizeAiText(text);
    const re=/\[\s*评论\s*\|([^\]]+)\]/g;
    let m;
    while((m=re.exec(src))){
      const parts=m[1].split('|').map(x=>String(x).trim()).filter((x, i, arr) => !(x === '' && i === arr.length - 1));
      let c = null;
      if(parts.length===3){
        // [作者|正文|时间]
        c = {author:parts[0], text:parts[1], time:parts[2]||nowHM()};
      }else if(parts.length===4){
        // 歧义：
        // A) [作者|被回复者|正文|时间]
        // B) [作者|头像|正文|时间]  ← AI 常按私信格式多写头像
        if (looksLikeAvatarToken(parts[1])) {
          c = {author:parts[0], avatar:parts[1], text:parts[2], time:parts[3]||nowHM()};
        } else {
          c = {author:parts[0], replyTo:parts[1], text:parts[2], time:parts[3]||nowHM()};
        }
      }else if(parts.length>=5){
        // [作者|头像|被回复者|正文|时间] 或 [作者|头像|正文|时间|多余]
        if (looksLikeAvatarToken(parts[1])) {
          if (looksLikeTimeToken(parts[3]) || looksLikeAvatarToken(parts[2])) {
            c = {author:parts[0], avatar:parts[1], text:parts[2], time:parts[3]||nowHM()};
          } else {
            c = {author:parts[0], avatar:parts[1], replyTo:parts[2], text:parts[3], time:parts[4]||nowHM()};
          }
        } else {
          c = {author:parts[0], replyTo:parts[1], text:parts[2], time:parts[3]||nowHM()};
        }
      }
      if (c) comments.push(scrubComment(c));
    }
    return comments;
  }

  function extractDmFromText(text, fallbackName){
    const msgs=[];
    const src=normalizeAiText(text);
    const re=/\[\s*(私信|分享微博)\s*\|([^\]]+)\]/g;
    let m;
    while((m=re.exec(src))){
      const kind=m[1];
      const parts=m[2].split('|').map(x=>String(x).trim());
      if(kind==='分享微博'){
        const hasAuthor=parts.length>=4;
        const author=hasAuthor ? parts[0] : (fallbackName||'路人');
        const ref=hasAuthor ? parts[1] : parts[0];
        const note=hasAuthor ? parts[2] : parts[1];
        const time=hasAuthor ? parts[3] : parts[2];
        const n=Number(String(ref||'').match(/\d+/)?.[0]||0);
        if(n>0) msgs.push({sender:'npc',author,avatar:'npc.png',type:'share',postIndex:n-1,text:note||'分享了一条微博',time:time||nowHM()});
        continue;
      }
      if(parts[0]==='我方消息' && parts.length>=3){
        msgs.push({sender:'user', text:parts[1], time:parts[2]||nowHM()});
      }else if(parts.length>=4){
        msgs.push({sender:'npc', author:parts[0], avatar:parts[1], text:parts[2], time:parts[3]||nowHM()});
      }else if(parts.length===3){
        msgs.push({sender:'npc', author:parts[0]||fallbackName||'路人', avatar:'npc.png', text:parts[1], time:parts[2]||nowHM()});
      }
    }
    return msgs;
  }

  function serializeOnePost(p, n){
    ensurePostEngagement(p);
    const lines=[`<post:${n}>`];
    lines.push(`[微博|${p.author}|${p.avatar||defaultUserAvatarToken()}|${p.text}|${p.time}|${p.likes||0}|${p.reposts||0}|${p.commentCount||0}]`);
    if(p.fakeImage) lines.push(`[伪图|${p.fakeImage}]`);
    (p.comments||[]).forEach(c=>{
      scrubComment(c);
      if(c.replyTo && !looksLikeAvatarToken(c.replyTo)) lines.push(`[评论|${c.author}|${c.replyTo}|${c.text}|${c.time}]`);
      else lines.push(`[评论|${c.author}|${c.text}|${c.time}]`);
    });
    lines.push(`</post:${n}>`);
    return lines.join('\n');
  }
  /** 该帖作者对应的粉丝基数（互动数 ≈ 粉/10） */
  function engagementFansBase(p){
    ensureProfileStats({ allowDefault: true });
    if (isCharAuthor(p?.author) || tokenMeansChar(p?.avatar)) {
      return Math.max(100, Number(state.charFans) || 10000);
    }
    if (isUserAuthor(p?.author) || tokenMeansUser(p?.avatar)) {
      return Math.max(50, Number(state.userFans) || 300);
    }
    const npc = npcAccounts().find((item) => [item.id, item.name].filter(Boolean).includes(String(p?.author || '')));
    if (npc) return Math.max(50, Number(npc.fans) || 300);
    // 路人/热门博：挂在角色粉量附近，别跳出本卡世界观
    const base = Math.max(1000, Number(state.charFans) || 20000);
    const h = hashSeed(String(p?.author || '路人'));
    return Math.max(300, Math.floor(base * (0.08 + (h % 55) / 100)));
  }
  /**
   * 赞 / 转 / 评（展示虚数）≈ 粉丝数的 1/10，再小幅抖动。
   * 真实 comments[] 仍只存几条热评，与展示数无关。
   */
  function fabricateEngagement(seedText, opts={}){
    const fans = Math.max(100, Number(opts.fans) || Number(state.charFans) || 10000);
    const h = hashSeed(String(seedText || '') + '|' + fans);
    const center = Math.max(1, Math.round(fans / 10));
    const likeMul = 0.5 + (h % 111) / 100; // 约 0.5x～1.6x · fans/10
    const likes = Math.max(1, Math.round(center * likeMul));
    const rpRatio = 0.25 + (h % 50) / 100;
    const reposts = Math.max(0, Math.round(likes * rpRatio));
    const cmRatio = 0.35 + (h % 55) / 100;
    const comments = Math.max(1, Math.round(likes * cmRatio));
    return { likes, reposts, comments, center };
  }
  function ensurePostEngagement(p){
    if (!p) return p;
    const fans = engagementFansBase(p);
    const fab = fabricateEngagement((p.text || '') + '|' + (p.author || ''), { fans });
    const center = Math.max(1, Math.round(fans / 10));
    const outOfBand = (n) => {
      n = Number(n) || 0;
      return !(n > 0) || n < center / 5 || n > center * 5;
    };
    let likes = Number(p.likes) || 0;
    let reposts = Number(p.reposts) || 0;
    let cmt = Number(p.commentCount) || 0;
    const real = (p.comments || []).length;
    if (outOfBand(likes)) likes = fab.likes;
    if (outOfBand(reposts) || reposts > likes) reposts = Math.min(fab.reposts, Math.max(0, likes));
    // 展示评论数：跟赞同量级；实际列表可以只有 5 条
    if (outOfBand(cmt) || cmt < real || (likes >= 20 && cmt < Math.floor(likes * 0.2))) {
      cmt = Math.max(fab.comments, real);
    }
    p.likes = likes;
    p.reposts = reposts;
    p.commentCount = Math.max(cmt, real);
    return p;
  }
  function displayCommentCount(p){
    ensurePostEngagement(p);
    return Math.max(Number(p.commentCount) || 0, (p.comments || []).length);
  }
  function bumpDisplayComments(p, added){
    if (!p) return;
    ensurePostEngagement(p);
    const real = (p.comments || []).length;
    let n = Number(p.commentCount) || 0;
    if (n < real) n = real;
    const add = Math.max(0, Number(added) || 0);
    if (add > 0) {
      const center = Math.max(1, Math.round(engagementFansBase(p) / 10));
      const jump = Math.max(add, Math.floor(center * (0.01 + (hashSeed(String(p.text || '') + n) % 4) / 100)));
      n += jump;
    }
    p.commentCount = Math.max(n, real);
  }
  /** 互动数展示：≥1万用「x.x万」，避免一长串 0 */
  function formatEngNumber(n){
    n = Number(n) || 0;
    if (n >= 100000000) {
      const v = n / 100000000;
      return (v >= 10 ? String(Math.round(v)) : String(Math.round(v * 10) / 10)) + '亿';
    }
    if (n >= 10000) {
      const v = n / 10000;
      // 10万以上取整；不足 10 万保留一位小数（如 1.2万）
      if (v >= 100) return String(Math.round(v)) + '万';
      if (v >= 10) return String(Math.round(v)) + '万';
      return (Math.round(v * 10) / 10).toFixed(1).replace(/\.0$/, '') + '万';
    }
    return String(Math.round(n));
  }
  function existingCommentAuthors(p){
    return [...new Set((p.comments||[]).map(c=>c.author).filter(Boolean))];
  }
  function existingDmContacts(){
    return state.threads.map(t=>t.name).filter(Boolean);
  }
  function recentWeiboTopics(limit=3){
    return state.posts.slice(0, limit).map((p,i)=>(`${i+1}. ${p.text.slice(0,80)}`)).join('\n') || '（暂无微博）';
  }
  function normalizeForDuplicateCheck(text){
    return String(text || '').toLowerCase().replace(/[\s\p{P}\p{S}]+/gu, '');
  }
  function ngramSet(text, size=3){
    const out = new Set();
    for (let i = 0; i <= text.length - size; i++) out.add(text.slice(i, i + size));
    return out;
  }
  function isNearDuplicatePostText(text){
    const incoming = normalizeForDuplicateCheck(text);
    if (!incoming) return true;
    return (state.posts || []).some((post) => {
      const old = normalizeForDuplicateCheck(post.text);
      if (!old) return false;
      if (incoming === old) return true;
      const shorter = Math.min(incoming.length, old.length);
      if (shorter >= 14 && (incoming.includes(old) || old.includes(incoming)) && shorter / Math.max(incoming.length, old.length) >= 0.72) return true;
      if (shorter < 18) return false;
      const a = ngramSet(incoming), b = ngramSet(old);
      let overlap = 0;
      a.forEach((item) => { if (b.has(item)) overlap++; });
      const union = a.size + b.size - overlap;
      return union > 0 && overlap / union >= 0.72;
    });
  }
  function lockGeneratedAccountIdentities(post, allowUserPost=false){
    if (!post) return null;
    const ids = configuredWeiboIds();
    const author = String(post.author || '').trim();
    const avatar = String(post.avatar || '').trim();
    const userHit = tokenMeansUser(avatar) || isUserAuthor(author);
    const charHit = tokenMeansChar(avatar) || isCharAuthor(author);
    const npcHit = npcAccounts().find((item) => [item.id,item.name].filter(Boolean).includes(author));
    if (userHit && !allowUserPost) return null;
    if (userHit) { post.author = ids.user || displayName; post.avatar = defaultUserAvatarToken(); }
    else if (charHit) { post.author = ids.char || displayChar; post.avatar = defaultCharAvatarToken(); }
    else if (npcHit) { post.author = npcHit.id || npcHit.name; post.avatar = 'npc.png'; }
    post.comments = (post.comments || []).filter((comment) => {
      const commentAuthor = String(comment.author || '').trim();
      if (isUserAuthor(commentAuthor)) return false;
      if (isCharAuthor(commentAuthor)) comment.author = ids.char || displayChar;
      const npcComment = npcAccounts().find((item) => [item.id,item.name].filter(Boolean).includes(commentAuthor));
      if (npcComment) comment.author = npcComment.id || npcComment.name;
      return true;
    });
    return post;
  }

  function mergeAiPayload(raw, opts={}){
    const text = normalizeAiText(raw);
    window.__weibo_last_ai_raw = text;
    console.log('[小微博] AI原文长度', text.length, '预览:', text.slice(0, 500));

    const a=parseWeiboApp(text), b=parseWeiboApp(`<weiboapp>${text}</weiboapp>`);
    const posts=a.posts.length?a.posts:b.posts;
    const threads=a.threads.length?a.threads:b.threads;

    if(opts.mode==='weibo' && typeof opts.postIndex==='number'){
      const target=state.posts[opts.postIndex];
      if(!target) return 0;
      const exist=new Set((target.comments||[]).map(c=>c.author+'|'+c.text));
      let allComments=[];
      posts.forEach(incoming => (incoming.comments||[]).forEach(c => allComments.push(c)));
      // 关键兜底：全文直接抠 [评论|...]
      if(!allComments.length) allComments = extractCommentsFromText(text);
      let added=0;
      allComments.forEach(c=>{
        if (isUserAuthor(c.author)) return;
        if (isCharAuthor(c.author)) c.author = configuredWeiboIds().char || displayChar;
        const npcComment = npcAccounts().find((item) => [item.id,item.name].filter(Boolean).includes(String(c.author||'')));
        if (npcComment) c.author = npcComment.id || npcComment.name;
        const visibility = visibilitySpec(target);
        if (visibility.type === 'private') return;
        if (visibility.type === 'group' && !visibilityAllows(target, c.author)) return;
        const k=c.author+'|'+c.text;
        if(!exist.has(k)){ target.comments.push(c); exist.add(k); added++; }
      });
      if (added > 0) bumpDisplayComments(target, added);
      else ensurePostEngagement(target);
      setUnreadOnTarget('comment', opts.postIndex, added);
      console.log('[小微博] 本帖新增评论', added, '/ 解析到', allComments.length);
      return added;
    }

    if(opts.mode==='feed'){
      let list = (posts || []).filter(p => String(p.text || '').trim());
      if(!list.length){
        // 兜底：尝试把全文按 post 块再解析一次已在 parseWeiboApp 做完
        return 0;
      }
      list = list.slice(0, 5);
      let addedPosts = 0;
      // 倒序 unshift，使 AI 输出的第 1 条出现在最上方
      for (let i = list.length - 1; i >= 0; i--) {
        const incoming = lockGeneratedAccountIdentities(list[i], false);
        if (!incoming || isNearDuplicatePostText(incoming.text)) continue;
        const comments = Array.isArray(incoming.comments) ? incoming.comments.slice() : [];
        const post = {
          author: incoming.author || '热门博主',
          avatar: incoming.avatar || '',
          text: incoming.text,
          time: incoming.time || today(),
          likes: Number(incoming.likes) || 0,
          reposts: Number(incoming.reposts) || 0,
          commentCount: Number(incoming.commentCount) || 0,
          fakeImage: incoming.fakeImage || '',
          comments: comments.slice(0, 5), // 实际只留最多 5 条热评
          unread: Math.min(5, comments.length),
          fromFeed: true,
        };
        ensurePostEngagement(post);
        state.posts.unshift(post);
        addedPosts++;
      }
      console.log('[小微博] 推荐拉取新增微博', addedPosts);
      return addedPosts;
    }

    if(opts.mode==='char-post' || opts.mode==='npc-post'){
      let list = (posts || []).filter(p => String(p.text || '').trim());
      if (!list.length) return 0;
      const npc = opts.mode === 'npc-post' ? npcAccounts().find((item) => item.key === opts.npcKey) : null;
      const who = npc ? (npc.id || npc.name) : (displayChar || rawCharName || '角色');
      let added = 0;
      for (let i = list.length - 1; i >= 0; i--) {
        const incoming = lockGeneratedAccountIdentities(list[i], false);
        if (!incoming || isNearDuplicatePostText(incoming.text)) continue;
        const comments = Array.isArray(incoming.comments) ? incoming.comments.slice() : [];
        const post = {
          author: who,
          avatar: npc ? 'npc.png' : defaultCharAvatarToken(),
          text: incoming.text,
          time: incoming.time || today(),
          likes: Number(incoming.likes) || 0,
          reposts: Number(incoming.reposts) || 0,
          commentCount: Number(incoming.commentCount) || 0,
          fakeImage: incoming.fakeImage || '',
          comments: comments.slice(0, 5),
          unread: Math.min(5, comments.length),
          fromCharPost: !npc,
          fromNpcPost: !!npc,
        };
        ensurePostEngagement(post);
        state.posts.unshift(post);
        added++;
      }
      // 发博后粉丝微增一点，写回楼层更像真账号
      ensureProfileStats();
      if (!npc) state.charFans = (Number(state.charFans) || 0) + (3 + (hashSeed(who + Date.now()) % 18));
      console.log('[小微博] 角色发博新增', added);
      return added;
    }

    if(opts.mode==='dm-scatter' || opts.mode==='dm'){
      let pool = threads;
      if(!pool.length){
        const loose=extractDmFromText(text);
        const byName={};
        loose.forEach(msg=>{
          const n=msg.author||'路人';
          if(!byName[n]) byName[n]=[];
          byName[n].push(msg);
        });
        pool = Object.keys(byName).map(n=>({name:n, messages:byName[n]}));
      }
      let added=0;
      pool.forEach(incoming=>{
        let hit=state.threads.find(t=>t.name===incoming.name);
        if(!hit){ hit={name:incoming.name,messages:[],unread:0}; state.threads.unshift(hit); }
        const exist=new Set(hit.messages.map(m=>(m.sender||'')+'|'+(m.author||'')+'|'+m.text));
        let round=0;
        (incoming.messages||[]).forEach(m=>{
          if (m.sender === 'user') return;
          bindSharedPost(m);
          if (m.type === 'share') { const shared=resolveSharedPost(m); if (!shared || !visibilityAllows(shared.post, m.author||incoming.name)) return; }
          const k=(m.sender||'')+'|'+(m.author||'')+'|'+m.text;
          if(exist.has(k)) return;
          hit.messages.push(m);
          exist.add(k);
          added++;
          if(m.sender !== 'user') round++;
        });
        setUnreadOnTarget('dm', incoming.name, round);
      });
      console.log('[小微博] 新增私信条数', added);
      return added;
    }

    if(opts.mode==='dm-thread' && opts.threadName){
      let hit=state.threads.find(t=>t.name===opts.threadName);
      if(!hit){ hit={name:opts.threadName,messages:[],unread:0}; state.threads.unshift(hit); }
      const exist=new Set(hit.messages.map(m=>(m.sender||'')+'|'+(m.author||'')+'|'+m.text));
      const matched=threads.find(t=>t.name===opts.threadName);
      let pool=matched ? matched.messages : threads.flatMap(t=>t.messages||[]);
      if(!pool.length) pool = extractDmFromText(text, opts.threadName);
      let added=0;
      pool.forEach(m=>{
        if (m.sender === 'user') return;
        const msg = bindSharedPost({sender:'npc', author:m.author||opts.threadName, avatar:m.avatar, text:m.text, time:m.time, ...(m.type==='share' ? {type:'share',postIndex:Number(m.postIndex)} : {})});
        if (msg.type === 'share') { const shared=resolveSharedPost(msg); if (!shared || !visibilityAllows(shared.post, msg.author||opts.threadName)) return; }
        const k=(msg.sender||'')+'|'+(msg.author||'')+'|'+msg.text;
        if(!exist.has(k)){ hit.messages.push(msg); exist.add(k); added++; }
      });
      setUnreadOnTarget('dm', opts.threadName, added);
      return added;
    }

    // fallback
    posts.forEach(incoming=>{
      incoming = lockGeneratedAccountIdentities(incoming, false);
      if (!incoming || isNearDuplicatePostText(incoming.text)) return;
      const hit=state.posts.find(p=>p.text===incoming.text && p.author===incoming.author);
      if(hit){
        const exist=new Set(hit.comments.map(c=>c.author+'|'+c.text));
        incoming.comments.forEach(c=>{ const k=c.author+'|'+c.text; if(!exist.has(k)) hit.comments.push(c); });
      }else if(incoming.text) state.posts.unshift(incoming);
    });
    threads.forEach(incoming=>{
      let hit=state.threads.find(t=>t.name===incoming.name);
      if(!hit){ hit={name:incoming.name,messages:[]}; state.threads.unshift(hit); }
      const exist=new Set(hit.messages.map(m=>(m.sender||'')+'|'+(m.author||'')+'|'+m.text));
      incoming.messages.forEach(m=>{ if(m.sender==='user') return; const k=(m.sender||'')+'|'+(m.author||'')+'|'+m.text; if(!exist.has(k)) hit.messages.push(m); });
    });
    return 0;
  }

  // ---- render ----
  function ensurePostId(post){
    if (post && !post.id) post.id = 'post_' + hashSeed(`${post.author||''}|${post.time||''}|${post.text||''}`).toString(36);
    return post?.id || '';
  }
  function bindSharedPost(message){
    if (!message || message.type !== 'share') return message;
    const post = state.posts[Number(message.postIndex)];
    if (post) message.postId = ensurePostId(post);
    return message;
  }
  function resolveSharedPost(message){
    if (message?.postId) {
      const index = state.posts.findIndex((post) => ensurePostId(post) === message.postId);
      if (index >= 0) return { post:state.posts[index], index };
    }
    const index = Number(message?.postIndex);
    return Number.isFinite(index) && state.posts[index] ? { post:state.posts[index], index } : null;
  }
  function visibilitySpec(post){
    const value = post?.visibility && typeof post.visibility === 'object' ? post.visibility : { type:'public', allow:[] };
    return { type:['public','private','group'].includes(value.type) ? value.type : 'public', allow:Array.isArray(value.allow) ? value.allow.map(String) : [] };
  }
  function visibilityLabel(post){
    const spec = visibilitySpec(post);
    if (spec.type === 'private') return '🔒 仅自己可见';
    if (spec.type === 'group') return `👥 部分可见：${spec.allow.join('、') || '未选择账号'}`;
    return '';
  }
  function visibilityAllows(post, viewer){
    const spec = visibilitySpec(post);
    if (spec.type === 'public') return true;
    if (spec.type === 'private') return false;
    const who = String(viewer || '').trim();
    const npc = npcAccounts().find((item) => [item.id,item.name].filter(Boolean).includes(who));
    return spec.allow.some((id) => id === who)
      || (isCharAuthor(who) && spec.allow.includes(String(configuredWeiboIds().char || displayChar)))
      || (!!npc && spec.allow.includes(String(npc.id || npc.name)));
  }
  function shareablePostsFor(viewer){
    return (state.posts || []).map((post, index) => ({ post, index })).filter(({ post }) => visibilityAllows(post, viewer));
  }
  function shareablePostsPrompt(viewer, publicOnly=false){
    const list = (state.posts || []).map((post, index) => ({ post, index })).filter(({ post }) => publicOnly ? visibilitySpec(post).type === 'public' : visibilityAllows(post, viewer));
