  async function unwrapUtilityAiResult(result){
    if (result == null) return '';
    if (typeof result === 'string') return result;
    if (typeof result.then === 'function') return unwrapUtilityAiResult(await result);
    if (result && typeof result[Symbol.asyncIterator] === 'function') {
      let out = '';
      for await (const chunk of result) out += typeof chunk === 'string' ? chunk : String(chunk?.content ?? chunk?.text ?? '');
      return out;
    }
    return String(result?.content ?? result?.message ?? result?.text ?? result?.result ?? result ?? '');
  }
  async function requestUtilityAi(kind, systemText, userText, button){
    if (state.aiBusy) throw new Error('已有 AI 请求正在进行，请稍候');
