    state.aiBusy = true;
    setRequestLoading(kind, true);
    const oldText = button?.textContent || '';
    if (button) { button.disabled = true; button.classList.add('loading'); button.textContent = kind === 'npc-account-build' ? '正在生成 NPC…' : '正在生成 ID…'; }
    try {
      const messages = [{ role:'system', content:systemText }, { role:'user', content:userText }];
      const request = AI_GENERATE_RAW
        ? { messages, ordered_prompts:['user_input'], user_input:userText, should_silence:true, should_stream:true }
        : { ordered_prompts:messages.map((item, index) => ({ role:item.role, content:item.content, position:'in_chat', depth:index ? 0 : 4, should_scan:false })) };
      const result = AI_GENERATE_RAW ? await AI_GENERATE_RAW(request) : await AI_GENERATE(request);
      const text = normalizeAiText(await unwrapUtilityAiResult(result));
      if (!String(text || '').trim()) throw new Error('API 返回空内容');
      return text;
    } finally {
      state.aiBusy = false;
      setRequestLoading(kind, false);
      if (button) { button.disabled = false; button.classList.remove('loading'); button.textContent = oldText; }
    }
  }
