    const snap = Array.isArray(phoneSettings.hotMemeLoreSnap) ? phoneSettings.hotMemeLoreSnap : (currentSlotContext().hotMemeLoreSnap || []);
    const map = new Map([...live, ...snap].map((item) => [String(item.id), item]));
