      if (!item) return '';
      const claimKey = loreClaimKey(item, id);
      if (claimedLoreIds?.has(claimKey)) return `【${item.name || item.id}】（完整内容已在本次请求前序位置注入；此处仅标记为可用梗）`;
      claimedLoreIds?.add(claimKey);
