      if (!enabled || !text) return;
      const depth = Math.max(0, Math.min(20, Number(depthOverride ?? depths[key] ?? 4) || 0));
      entries.push({ key, title, content:text, depth, order:entries.length });
    };
    add('character', 'Character Card', groups.character.concat(historyContext.includeBaiBaiHistory ? [] : groups.other).join('\n\n'), phoneSettings.includeChar !== false || phoneSettings.includeScenario !== false);
