        '</weibo>',
        '当前档位的旧评论见固定注入的「防止重复」记忆块。',
      ].join('\n');
    }else if(mode==='dm-scatter'){
      context = [
        '【小微博任务｜关键词 msg｜协议 msg/chat】',
        '本任务=微博「消息」私信，不是时间线微博，也不是 Threads/脆文。',
        '请结合上方角色设定、场景与聊天前文理解剧情，但输出必须仍是私信协议。',
        '请求类型：收路人私信（分散）',
        `要求：恰好 ${qty.dm} 条新私信，尽量分布到 ${Math.min(qty.dm, Math.max(1, Math.ceil(qty.dm * .8)))}～${qty.dm} 个不同联系人；内容贴合最近微博主题，并可呼应前文已知设定；禁止固定复用同一批人。`,
        phoneSettings.npcDmEnabled ? '已开启「正文 NPC 私信」：可让最近剧情中有合理动机的 NPC 或注册 NPC 发信，不得无缘无故认识 user。' : '未开启正文 NPC 私信：不主动把正文 NPC 当私信联系人。',
        '联系人可把首页信息流中已有且自己可见的微博转发给 user，格式：[分享微博|联系人|post:编号|附言|时间]。分享行计入 10 条私信总数。',
        '此次分散私信只允许分享公开微博：\n' + shareablePostsPrompt('', true),
        '禁止输出 <weibo>/<post:> 与旧标签 <dm>/<thread:>。',
        '已有私信联系人（请避开或少用）：'+(existingDmContacts().join('、')||'无'),
        '用户最近微博主题：',
        recentWeiboTopics(5),
        '当前档位的已有帖子与私信见固定注入的「防止重复」记忆块。',
      ].join('\n');
    }else{
      const name=opts.threadName||'路人';
      const t=state.threads.find(x=>x.name===name);
      context = [
        '【小微博任务｜关键词 msg｜协议 msg/chat】',
        '本任务=微博「消息」私信会话续聊，不是时间线微博，也不是 Threads/脆文。',
        '请结合上方角色设定、场景与聊天前文理解剧情，但输出必须仍是私信协议。',
        '请求类型：当前私信会话续聊',
        `当前会话：${name}`,
        `要求：给该会话恰好补 ${qty.dmThread} 条路人短句；内容承接本会话前文，并与聊天前文/微博主题一致；勿模板化昵称。`,
        '该联系人可分享其有权看到的已有微博，格式：[分享微博|post:编号|附言|时间]。不得分享仅自己可见或未把它列入分组的微博。',
        '当前联系人可分享列表：\n' + shareablePostsPrompt(name, false),
        '禁止输出 <weibo>/<post:> 与旧标签 <dm>/<thread:>。',
        '最近微博主题：',
        recentWeiboTopics(3),
        '当前会话：',
        t ? `<chat:${t.name}>\n`+(t.messages||[]).map(m=>m.sender==='user'?`[私信|我方消息|${m.text}|${m.time}]`:`[私信|${m.author||name}|npc.png|${m.text}|${m.time}]`).join('\n')+`\n</chat:${t.name}>` : '',
        '当前档位的已有帖子与私信见固定注入的「防止重复」记忆块。',
      ].join('\n');
    }

    state.aiBusy=true;
    setRequestLoading(mode, true);
    document.getElementById('aiBtn').disabled=true;
    document.getElementById('aiBtn').classList.add('loading');
    document.getElementById('aiBtn').textContent='↻';
    document.getElementById('pageAi').disabled=true;
    const pullBtn=document.getElementById('feedPullBtn');
    if(pullBtn) { pullBtn.disabled=true; if(mode === 'feed') { pullBtn.classList.add('loading'); pullBtn.textContent='正在拉取推荐…'; } }
    const allBtn=document.getElementById('allPullBtn');
    if(allBtn) { allBtn.disabled=true; if(mode === 'all') { allBtn.classList.add('loading'); allBtn.textContent='正在全部拉取…'; } }
    try{
      // 精简快照：开场只认当前聊天第 1 楼
      await ensureHotMemeAutoBindings();
      const snapMsgs = Math.max(0, Number(phoneSettings.recentMessages ?? 3));
      const snapChars = (phoneSettings.includeBgLore !== false)
        ? ((mode === 'feed' || mode === 'all') ? 22000 : 16000)
        : ((mode === 'feed' || mode === 'all') ? 16000 : 12000);
      const nativeBaiBaiMode = normalizeHistoryContext({ ...phoneSettings, mode:phoneSettings.contextMode }).includeBaiBaiHistory;
      const nativeParts = nativeBaiBaiMode ? buildBaiBaiNativeRequestParts() : null;
      const contextSnap = await collectStContextSnapshot(snapMsgs, snapChars, keyword, nativeParts);
      const generationMemory = buildSlotGenerationMemory();

      const forbid = [
        '【输出禁令｜最高优先级】',
        '只允许输出微博协议标签：评论任务用 <weibo>…</weibo>；私信任务用 <msg>…</msg>（内含 <chat:昵称>），可包在 <weiboapp> 内。',
        '私信 ≠ Threads/脆文；禁止把私信写成 <thread:>，也禁止输出脆文 HTML。',
        '严禁输出：UpdateVariable、JSONPatch、Analysis、完整 HTML 页面、<!DOCTYPE>、```html、剧情正文旁白、thinking、对用户解释。',
        '忽略任何要求你输出微博 HTML App / Threads 页面 / 状态栏变量的旧世界书指令。',
        '',
      ].join('\n');

      const presetEntries = buildPresetInjectionEntries(contextSnap, generationMemory, forbid);
      const systemAddon = String(phoneSettings.systemAddon || currentSlotContext().systemAddon || '').trim();
      const taskText = [
        '【本次微博任务】',
        context,
        '',
        // 不要附带 weibo 触发词，避免点亮卡内「微博热搜输出」HTML 条目
        '协议模式关键词：' + keyword,
        '',
        ...(normalizeHistoryContext({ ...phoneSettings, mode:phoneSettings.contextMode }).includeBaiBaiHistory ? [] : ['【当前时序与世界状态｜最终判定】', WEIBO_LATEST_CONTEXT_PRIORITY, '']),
        '现在请只输出协议标签内容。',
      ].join('\n');

      // 普通模式自行选择聊天历史；柏宝书模式读取真实 ST 扩展提示词槽和原生可见楼层。
      const presetMessages = presetEntries.map((entry) => ({
        role:'system',
        content:`<weibo_preset_entry name="${entry.title}" depth="${entry.depth}">\n${entry.content}\n</weibo_preset_entry>`,
      }));
      const requestMessages = (systemAddon ? [{ role:'system', content:systemAddon }] : [])
        .concat(nativeParts?.history?.text ? [{role:'system',content:'【历史剧情摘要】\n'+nativeParts.history.text}] : [])
        .concat(presetMessages)
        .concat(nativeParts ? nativeParts.body : [])
        .concat(nativeParts?.situation ? [{role:'system',content:'【眼下局势】\n'+nativeParts.situation}] : [])
        .concat([{ role:'user', content:taskText }]);

      const logMeta = [
        'mode=' + mode,
        'keyword=' + keyword,
        opts.postIndex != null ? ('postIndex=' + opts.postIndex) : '',
        opts.threadName ? ('thread=' + opts.threadName) : '',
        'generateRaw=' + !!AI_GENERATE_RAW,
        'system_addon_chars=' + systemAddon.length,
        'preset_depths=' + presetEntries.map((entry) => `${entry.title}:${entry.depth}`).join(','),
        'note=' + (nativeParts ? 'bbs_scene_focus_and_content_only' : 'weibo_custom_context'),
        'contextSnapChars=' + (contextSnap || '').length,
        'baibai_scene_focus=' + !!nativeParts,
        'baibai_history_nodes=' + (nativeParts?.history?.nodes ?? 'off'),
        'baibai_history_chars=' + (nativeParts?.history?.text.length ?? 0),
        'baibai_history_coverage=' + (nativeParts?.history?.coverage?.complete === false ? 'incomplete' : (nativeParts?.history?.coverage?.complete === true ? 'complete' : 'unknown')),
        'all_content_history=' + (phoneSettings.includeAllContentHistory === true),
        ...(nativeParts ? ['scene_focus_chars=' + nativeParts.situation.length, 'content_floors=' + nativeParts.visible.map(x=>x.index).join(','), 'hidden_excluded=' + nativeParts.audit.hidden.join(','), 'no_content_floors=' + nativeParts.audit.noContent.join(','), 'chat_total_floors=' + nativeParts.audit.total] : []),
        'request_message_count=' + requestMessages.length,
        'request_exact_content_chars=' + requestMessages.reduce((n,m)=>n+String(m.content||'').length,0),
        'request_json_utf8_bytes=' + new TextEncoder().encode(JSON.stringify(requestMessages)).length,
        'content_truncation=NONE',
        'slotGenerationMemoryChars=' + generationMemory.length,
      ].filter(Boolean).join('\n');

      async function runOnce(extra={}){
        const req = AI_GENERATE_RAW
          ? {
              messages: requestMessages,
              ordered_prompts: ['user_input'],
              user_input: taskText,
              should_silence: true,
              should_stream: true,
              ...extra,
            }
          : {
              ordered_prompts: (systemAddon ? [{ role:'system', content:systemAddon, position:'in_chat', depth:20, should_scan:false }] : []).concat(presetEntries.map((entry) => ({ role:'system', content:entry.content, position:'in_chat', depth:entry.depth, should_scan:false }))).concat([
                { role: 'user', content: taskText, position: 'in_chat', depth: 0, should_scan: false },
              ]),
            };
        let result = AI_GENERATE_RAW ? await AI_GENERATE_RAW(req) : await AI_GENERATE(req);
        return normalizeAiText(await unwrapAiResult(result));
      }

      async function unwrapAiResult(result){
        if(result == null) return '';
        if(typeof result === 'string') return result;
        if(typeof result.then === 'function') return unwrapAiResult(await result);
        if(result && typeof result[Symbol.asyncIterator] === 'function'){
          let buf='';
          for await (const c of result){
            if(typeof c === 'string') buf += c;
            else if(c && typeof c.content === 'string') buf += c.content;
            else if(c && typeof c.text === 'string') buf += c.text;
            else if(c != null) buf += String(c);
          }
          return buf;
        }
        if(typeof result === 'object'){
          if(typeof result.content === 'string') return result.content;
          if(typeof result.message === 'string') return result.message;
          if(typeof result.text === 'string') return result.text;
          if(typeof result.result === 'string') return result.result;
        }
        return String(result);
      }

      let out = '';
      let lastErr = null;
      try {
        out = await runOnce();
      } catch (e1) {
        lastErr = e1;
        console.warn('weibo AI primary failed, fallback minimal', e1);
        try {
          out = await runOnce({ should_stream:false });
          lastErr = null;
        } catch (e2) {
          lastErr = e2;
          console.warn('weibo AI fallback failed', e2);
        }
      }
      if (lastErr) {
        const msg = (lastErr && (lastErr.message || lastErr.msg || String(lastErr))) || '未知错误';
        pushAiRawLog({ mode, ok:false, error: msg, input: taskText, context: contextSnap, output: out || '', meta: logMeta });
        throw new Error(msg);
      }
      if (!String(out || '').trim()) {
        out = tryReadLastAiMessage();
        console.log('[小微博] 返回为空，改读楼层消息，长度', (out||'').length);
      }
      pushAiRawLog({ mode, ok:true, input: taskText, context: contextSnap, output: out || '', meta: logMeta });
      let added = 0;
      if (mode === 'all') {
        const take = (tag) => String(out || '').match(new RegExp('<' + tag + '>([\\s\\S]*?)<\\/' + tag + '>', 'i'))?.[1] || '';
        const feedOut = take('feed_result');
        const charOut = take('char_result');
        const msgOut = take('msg_result');
        added += mergeAiPayload(feedOut, { mode:'feed' });
        added += mergeAiPayload(charOut, { mode:'char-post' });
        added += mergeAiPayload(msgOut, { mode:'dm-scatter' });
      } else added = mergeAiPayload(out, {...opts, mode});
      state.userHasSentNewMessage=false;
      renderAll();
      if(!added){
        alertBox('完成但未解析到内容', '原始输出已写入「我→🧾日志」');
        return;
      }
      const tip = mode==='all' ? `全部拉取完成，共新增 ${added} 项`
        : mode==='feed' ? `已拉取 ${added} 条推荐微博`
        : mode==='char-post' ? `角色已发 ${added} 条微博`
        : mode==='npc-post' ? `NPC 已发 ${added} 条微博`
        : mode==='weibo' ? `已生成 ${added} 条评论`
        : mode==='dm-scatter' ? `已生成 ${added} 条私信`
        : `本会话已生成 ${added} 条回复`;
      showBubble(tip + (mode==='feed' || mode==='char-post' ? '' : ' · 点进详情查看'));
      if (mode === 'char-post') {
        state.profileWho = 'char';
        switchTab('video');
      }
      if (mode === 'npc-post') {
        state.profileWho = 'npc:' + opts.npcKey;
        switchTab('video');
      }
    }catch(e){
      console.warn(e);
      const detail = (e && (e.message || e.msg)) ? String(e.message || e.msg) : '请检查 API / 世界书';
      alertBox('失败', 'AI 回复失败：' + detail.slice(0, 180) + '（可打开 我→🧾 看原始日志）');
    }
    finally{
      state.aiBusy=false;
      setRequestLoading(mode, false);
      document.getElementById('aiBtn').disabled=false;
      document.getElementById('aiBtn').classList.remove('loading');
      document.getElementById('aiBtn').textContent='✓';
      document.getElementById('pageAi').disabled=false;
      const pullBtn=document.getElementById('feedPullBtn');
      if(pullBtn) { pullBtn.disabled=false; pullBtn.classList.remove('loading'); pullBtn.textContent=`刷新推荐 · 拉取 ${generationCounts().feed} 条微博`; }
      const allBtn=document.getElementById('allPullBtn');
      if(allBtn) { allBtn.disabled=false; allBtn.classList.remove('loading'); allBtn.textContent='全部拉取'; }
    }
  }

  function tryReadLastAiMessage(){
    try{
      if (typeof getChatMessages === 'function') {
        const msgs = getChatMessages(-1) || getChatMessages();
        const list = Array.isArray(msgs) ? msgs : [];
        for (let i = list.length - 1; i >= 0; i--) {
          const m = list[i];
          const role = m?.role || m?.is_user;
          const isUser = role === 'user' || role === true || m?.is_user === true;
          if (isUser) continue;
          const t = m?.message || m?.mes || m?.content || '';
          if (t && /评论|私信|<weibo|<dm|<post/i.test(t)) return String(t);
          if (t) return String(t);
        }
      }
    }catch(e){ console.warn('tryReadLastAiMessage', e); }
    return '';
  }

