  function openCommentNotices(){
    const items = state.posts
      .map((p, i) => ({ p, i, ur: Number(p.unread) || 0, cm: (p.comments || []).length }))
      .filter(x => x.cm > 0)
      .sort((a, b) => (b.ur - a.ur) || (b.i - a.i));
    // 列表展示未读红点；点进正文后 clearPostUnread，红点消失
    if (!items.length) {
      showBubble('暂无评论通知');
      return;
    }
    const list = items.map(({ p, i, ur, cm }) => `
      <div class="msg-row" data-open-notice="${i}">
        <div class="ico" style="background:#ffd6c2;overflow:hidden;padding:0;position:relative">${avatarInner(p.author, p.avatar)}${ur?badgeHTML(ur):''}</div>
        <div class="mid">
          <div class="t">${esc(p.author)} 的微博</div>
          <div class="p">${ur ? `${ur} 条未读 · ` : ''}${cm} 条评论 · ${esc(String(p.text || '').slice(0, 28))}${(p.text || '').length > 28 ? '…' : ''}</div>
        </div>
        <div class="right">${ur?`<div class="dot"></div>`:''}</div>
        <div class="chev">›</div>
      </div>`).join('');
    document.getElementById('pageBody').innerHTML = `
      <div style="padding:10px 14px;font-size:12px;color:#999;background:#fff">未读条目带红点；点开后红点消失（列表不展示评论正文）</div>
      ${list}`;
    document.getElementById('pageTitle').textContent = '评论';
    document.getElementById('page').classList.add('show');
    state.page = { type: 'notices' };
    document.getElementById('pageBody').onclick = (e) => {
      const row = e.target.closest('[data-open-notice]');
      if (!row) return;
      openPost(Number(row.dataset.openNotice), { fromNotices: true });
