      const ch = ctx?.characters?.[ctx?.characterId];
      const data = ch?.data || ch || {};
      if (document.getElementById('setIncludeChar')?.checked) {
        if (data.description || ch?.description) lines.push('【角色描述】\n' + String(data.description || ch.description));
        if (data.personality || ch?.personality) lines.push('【角色性格】\n' + String(data.personality || ch.personality));
