  function estimateTokens(text){
    const value = String(text || '').trim();
    if (!value) return 0;
    const cjk = (value.match(/[\u3400-\u9fff\uf900-\ufaff\u3040-\u30ff\uac00-\ud7af]/g) || []).length;
    const rest = value.replace(/[\u3400-\u9fff\uf900-\ufaff\u3040-\u30ff\uac00-\ud7af]/g, '');
    return Math.max(1, Math.ceil(cjk * 1.05 + rest.length / 3.8));
  }
  function recentHistoryForTokenEstimate(){
    const includeRecent = document.getElementById('setIncludeRecentContext')?.checked ?? phoneSettings.includeRecentContext ?? true;
    const includeSummary = document.getElementById('setIncludeSummaryContext')?.checked ?? phoneSettings.includeSummaryContext ?? false;
    const includeOpening = document.getElementById('setIncludeOpeningContext')?.checked ?? phoneSettings.includeOpeningContext ?? false;
    const includeBaiBai = document.getElementById('setIncludeBaiBaiHistory')?.checked ?? phoneSettings.includeBaiBaiHistory ?? false;
    const allHistory = document.getElementById('setIncludeAllContentHistory')?.checked ?? phoneSettings.includeAllContentHistory === true;
    if (includeBaiBai) {
      try { const parts = buildBaiBaiNativeRequestParts(); return [parts.history.text,includeSummary ? String(document.getElementById('setManualSummary')?.value || phoneSettings.manualSummary || '') : '',parts.situation,...parts.visible.map(x=>x.content)].filter(Boolean).join('\n\n'); }
      catch (_) { return ''; }
    }
    if (allHistory) return nativeBaiBaiFloorAudit(null,true,includeOpening).visible.map(x=>x.content).join('\n\n');
    const chunks = [];
    if (includeSummary) chunks.push(String(document.getElementById('setManualSummary')?.value || phoneSettings.manualSummary || ''));
    if (includeRecent) {
      const count = Math.max(0, Math.min(60, Number(document.getElementById('setRecentMessages')?.value ?? phoneSettings.recentMessages ?? 3) || 0));
      try {
        const chat = getSillyContextSafe()?.chat || [];
        if (count > 0) chunks.push(chat.slice(-count).map((msg) => extractContentOnly(msg?.mes ?? msg?.content)).filter(Boolean).join('\n\n'));
      } catch (_) {}
    }
    if (includeOpening) {
      try { chunks.push(extractContentOnly(readFullChatMessageList()[0]?.mes || '')); } catch (_) {}
    }
    return chunks.filter(Boolean).join('\n\n');
  }
