  function loreBindingsFromNames(bookName, entryNames){
    const cleanBook = String(bookName || '').replace(/^(世界书:|角色书:)/, '').trim().toLowerCase();
    const wantedEntries = String(entryNames || '').split(/[、；;]+/).map((item) => item.trim().toLowerCase()).filter(Boolean);
    const matches = [];
    (_loreCatalogCache?.books || []).forEach((book) => {
      const liveBook = String(book.label || book.key || '').replace(/^(世界书:|角色书:)/, '').trim();
      if (cleanBook && liveBook.toLowerCase() !== cleanBook && !liveBook.toLowerCase().includes(cleanBook) && !cleanBook.includes(liveBook.toLowerCase())) return;
      (book.entries || []).forEach((entry) => {
        const liveName = String(entry.name || '').replace(/^［禁用］/, '').trim();
        if (wantedEntries.length && !wantedEntries.some((name) => liveName.toLowerCase() === name || liveName.toLowerCase().includes(name))) return;
        matches.push({ book:liveBook, entry:liveName });
      });
    });
    return normalizePortableLoreBindings(matches);
  }
  function parseNpcGenerationOutput(text){
    const rows = [];
    const re = /\[NPC\|([^\]\n]+)\]/gi;
    let match;
    while ((match = re.exec(String(text || '')))) {
      const parts = match[1].split('|').map((item) => item.trim());
      if (parts.length < 8) continue;
      const [id, name, bio, fans, following, manualLore, postPrompt, sourceBook='', sourceEntries=''] = parts;
      if (!id || !name) continue;
      const bindings = loreBindingsFromNames(sourceBook, sourceEntries);
      const loreIds = [...portableLoreIds(_loreCatalogCache?.books || [], bindings)];
      const catalog = new Map((_loreCatalogCache?.flat || []).map((item) => [String(item.id), item]));
      rows.push(normalizeNpcAccount({
        key:'npc_' + Date.now().toString(36) + '_' + rows.length,
        id:id.replace(/^@/, ''), name, bio, fans:parseFanNumber(fans), following:parseFanNumber(following), manualLore, postPrompt,
        lorePortableBindings:bindings, loreIds,
        loreSnap:loreIds.map((value) => catalog.get(String(value))).filter(Boolean).map((item) => ({ id:item.id, book:item.book, name:item.name, content:String(item.content || '').slice(0,8000) })),
      }, rows.length));
    }
    return rows;
  }
  function parseIdGenerationOutput(text){
    const rows = [];
    const re = /\[ID\|([^\]\n]+)\]/gi;
    let match;
    while ((match = re.exec(String(text || '')))) {
      const parts = match[1].split('|').map((item) => item.trim());
      const id = parts[0] || '';
      if (!id) continue;
      rows.push({ id, weight:Math.max(1, Math.min(10, Number(parts[1]) || 5)), attributes:parts.slice(2).join('，').trim() });
    }
    return rows;
  }
