        existing.length ? `历次已经存在的 NPC 账号（本次严禁重复名字、ID 或换壳生成）：${existing.map((item) => `${item.name}/${item.id}`).join('、')}` : '当前尚无已注册 NPC。',
        extra ? `用户额外要求：${extra}` : '',
        '每个 NPC 只输出一行，严格格式：',
        '[NPC|微博ID|正文姓名/称呼|公开简介|粉丝数纯数字|关注数纯数字|身份关系与说话方式设定|NPC发帖要求|来源世界书名称|来源条目名称]',
        '字段内禁止出现英文竖线、方括号或换行。微博 ID 不带 @；ID 要像真人网名并贴合人物。身份设定写清与 user/char 的关系、性格、口吻和知情边界；发帖要求写可公开主题、表达习惯与禁忌。来源条目有多个时用中文分号隔开。',
        '用 <npc_accounts> 包住所有行，标签外不要输出任何文字。',
        identityContext,
        '', '【当前选择的世界书正文】', lore,
      ].filter(Boolean).join('\n');
      const out = await requestUtilityAi('npc-account-build', system, user, button);
      const generated = parseNpcGenerationOutput(out);
      if (!generated.length) throw new Error('API 已返回，但没有解析到 [NPC|…] 行');
      const merged = [...existing];
      const seen = new Set(existing.flatMap((item) => [item.id, item.name]).map((value) => String(value || '').trim().toLowerCase()).filter(Boolean));
      generated.forEach((npc) => {
        const keys = [npc.id, npc.name].map((value) => String(value || '').trim().toLowerCase()).filter(Boolean);
