  function splitSnapshotForPresetPreview(snapshot){
    const groups = { init:[], character:[], persona:[], history:[], recent:[], nativeBaiBai:[], worldbook:[], custom:[], other:[] };
    const re = /^### ([^\n]+)\n([\s\S]*?)(?=\n\n### |(?![\s\S]))/gm;
    let match;
    while ((match = re.exec(String(snapshot || '')))) {
      const title = match[1].trim();
      const block = `### ${title}\n${match[2].trim()}`;
      if (/^柏宝书历史剧情摘要$|^眼下局势$|^聊天正文（仅 content|^柏宝书原生/.test(title)) groups.nativeBaiBai.push(block);
      else if (/初始化|wb_lore|钉住设定/.test(title)) groups.init.push(block);
      else if (/用户 Persona|User Personality|用户显示名/.test(title)) groups.persona.push(block);
      else if (/角色|性格|场景|显示名/.test(title)) groups.character.push(block);
      else if (/世界书|手机相关设定/.test(title)) groups.worldbook.push(block);
      else if (/自定义条目/.test(title)) groups.custom.push(block);
      else if (/最近聊天完整正文|最新聊天时序判定/.test(title)) groups.recent.push(block);
      else if (/聊天正文（全部前文|聊天|开场|前文|柏宝书历史剧情摘要/.test(title)) groups.history.push(block);
      else groups.other.push(block);
    }
    return groups;
  }

